            "label": "Projects",
            "status": "ok",
            "message": f"{count} project(s) configured",
            "details": {"count": count},
        }
    except Exception:
        return {
            "name": "projects_usage",
            "label": "Projects",
            "status": "warn",
            "message": "projects.json exists but unreadable",
        }


def _check_deprecated_config(palaia_root: Path | None) -> dict[str, Any]:
    """Check for deprecated or missing config keys."""
    if palaia_root is None:
        return {
            "name": "deprecated_config",
            "label": "Config keys",
            "status": "error",
            "message": "Not initialized",
        }

    from palaia.config import load_config

    config = load_config(palaia_root)
    issues = []

    # Check for legacy embedding_provider without chain
    if config.get("embedding_provider") and config.get("embedding_provider") != "auto":
        if not config.get("embedding_chain"):
            issues.append(
                "embedding_provider is set but embedding_chain is not — "
                "run: palaia detect && palaia config set-chain <providers> bm25"
            )

    if issues:
        return {
            "name": "deprecated_config",
            "label": "Config keys",
            "status": "warn",
            "message": f"{len(issues)} issue(s)",
            "fix": "\n".join(issues),
            "details": {"issues": issues},
        }

    return {
        "name": "deprecated_config",
        "label": "Config keys",
        "status": "ok",
        "message": "All config keys current",
    }


def _check_entry_classes(palaia_root: Path | None) -> dict[str, Any]:
    """Check entry class adoption and suggest migration for untyped entries."""
    if palaia_root is None:
        return {
            "name": "entry_classes",
            "label": "Entry classes",
            "status": "error",
            "message": "Not initialized",
        }

    from palaia.entry import parse_entry

    total = 0
    untyped = 0
    type_counts: dict[str, int] = {}

    for tier in ("hot", "warm", "cold"):
        tier_dir = palaia_root / tier
        if not tier_dir.exists():
            continue
        for p in tier_dir.glob("*.md"):
            try:
                text = p.read_text(encoding="utf-8")
                meta, _ = parse_entry(text)
                total += 1
                et = meta.get("type")
                if et is None:
                    untyped += 1
                    et = "memory"
                type_counts[et] = type_counts.get(et, 0) + 1
            except Exception:
                continue

    if total == 0:
        return {
            "name": "entry_classes",
            "label": "Entry classes",
            "status": "info",
            "message": "No entries yet",
        }

    parts = [f"{v} {k}" for k, v in sorted(type_counts.items())]
    class_str = ", ".join(parts)

    if untyped > 0:
        return {
            "name": "entry_classes",
            "label": "Entry classes",
            "status": "info",
            "message": f"{class_str} ({untyped} untyped, default to memory)",
            "fix": "Run: palaia migrate --suggest  to get type recommendations",
            "details": {"total": total, "untyped": untyped, "types": type_counts},
        }

    return {
        "name": "entry_classes",
        "label": "Entry classes",
        "status": "ok",
        "message": class_str,
        "details": {"total": total, "types": type_counts},
    }


def _check_default_agent_alias(palaia_root: Path | None) -> dict[str, Any]:
    """Check if entries with agent='default' exist alongside named agents without an alias."""
    if palaia_root is None:
        return {
            "name": "default_agent_alias",
            "label": "Agent aliases",
            "status": "ok",
            "message": "Not initialized",
        }

    from palaia.config import load_config
    from palaia.entry import parse_entry

    config = load_config(palaia_root)
    aliases = config.get("aliases", {})

    # Scan all entries for agent names
    agents_seen: dict[str, int] = {}
    for tier in ("hot", "warm", "cold"):
        tier_dir = palaia_root / tier
        if not tier_dir.exists():
            continue
        for p in tier_dir.glob("*.md"):
            try:
                text = p.read_text(encoding="utf-8")
                meta, _ = parse_entry(text)
                agent = meta.get("agent", "")
                if agent:
                    agents_seen[agent] = agents_seen.get(agent, 0) + 1
            except Exception:
                continue

    default_count = agents_seen.get("default", 0)
    named_agents = {a for a in agents_seen if a != "default"}

    if default_count == 0 or not named_agents:
        return {
            "name": "default_agent_alias",
            "label": "Agent aliases",
            "status": "ok",
            "message": "No alias issues detected",
        }

    # Check if "default" has an alias set
    if "default" in aliases:
        target = aliases["default"]
        return {
            "name": "default_agent_alias",
            "label": "Agent aliases",
            "status": "ok",
            "message": f"default -> {target} ({default_count} entries aliased)",
        }

    # default entries exist + named agents exist + no alias
    return {
        "name": "default_agent_alias",
        "label": "Agent aliases",
        "status": "warn",
        "message": (
            f"You have {default_count} entries with agent='default' "
            f"but also named agents ({', '.join(sorted(named_agents))}). "
            f"These entries won't appear in agent-filtered queries."
        ),
        "fix": "Set an alias: palaia config set-alias default YOUR_NAME",
    }


def _check_version_available(palaia_root: Path | None) -> dict[str, Any]:
    """Check if a newer Palaia version is available on PyPI."""
    from palaia import __version__

    try:
        import urllib.request

        url = "https://pypi.org/pypi/palaia/json"
        req = urllib.request.Request(url, headers={"Accept": "application/json"})
        with urllib.request.urlopen(req, timeout=5) as resp:
            import json as _json

            data = _json.loads(resp.read())
            latest = data.get("info", {}).get("version", "")

        if not latest:
            return {
                "name": "version_check",
                "label": "Version check",
                "status": "ok",
                "message": f"v{__version__} (could not determine latest)",
            }

        if latest == __version__:
            return {
                "name": "version_check",
                "label": "Version check",
                "status": "ok",
                "message": f"v{__version__} (latest)",
                "details": {"installed": __version__, "latest": latest},
            }

        # Compare versions
        from packaging.version import InvalidVersion, Version

        try:
            if Version(latest) > Version(__version__):
                return {
                    "name": "version_check",
                    "label": "Version check",
                    "status": "warn",
                    "message": f"Update available: v{__version__} -> v{latest}",
                    "fix": "Run: pip install --upgrade palaia && palaia doctor --fix",
                    "details": {"installed": __version__, "latest": latest},
                }
        except InvalidVersion:
            pass

        return {
            "name": "version_check",
            "label": "Version check",
            "status": "ok",
            "message": f"v{__version__} (latest: v{latest})",
            "details": {"installed": __version__, "latest": latest},
        }
    except Exception:
        # Network failure, timeout, etc. — don't block doctor
        return {
            "name": "version_check",
            "label": "Version check",
            "status": "ok",
            "message": f"v{__version__} (offline — could not check PyPI)",
        }


def _check_unread_memos(palaia_root: Path | None) -> dict[str, Any]:
    """Check for unread memos addressed to the current agent."""
    if palaia_root is None:
        return {
            "name": "unread_memos",
            "label": "Unread memos",
            "status": "ok",
            "message": "Not initialized",
        }

    try:
        from palaia.config import get_agent, get_aliases
        from palaia.memo import MemoManager

        agent = get_agent(palaia_root)
        if not agent:
            agent = "default"

        mm = MemoManager(palaia_root)
        try:
            aliases = get_aliases(palaia_root)
        except Exception:
            aliases = None

        unread = mm.inbox(agent=agent, include_read=False, aliases=aliases or None)
        count = len(unread)

        if count == 0:
            return {
                "name": "unread_memos",
                "label": "Unread memos",
                "status": "ok",
                "message": "No unread memos",
            }

        # Collect preview of unread memos for --fix display
        previews = []
        for meta, body in unread:
            sender = meta.get("from", "?")
            prio = " [high]" if meta.get("priority") == "high" else ""
            first_line = body.split("\n")[0][:60] if body else ""
            previews.append(f"From {sender}{prio}: {first_line}")

        return {
            "name": "unread_memos",
            "label": "Unread memos",
            "status": "warn",
            "message": f"{count} unread memo(s)",
            "fix": "Run: palaia memo inbox",
            "details": {"count": count, "previews": previews},
        }
    except Exception:
        return {
            "name": "unread_memos",
            "label": "Unread memos",
            "status": "ok",
            "message": "Could not check memos",
        }


def _check_plugin_defaults_upgrade(palaia_root: Path | None) -> dict[str, Any]:
    """Check if plugin defaults need upgrading from v1.x to v2.0."""
    if palaia_root is None:
        return {
            "name": "plugin_defaults_upgrade",
            "label": "Plugin defaults",
            "status": "ok",
            "message": "Not initialized",
        }

    from palaia.config import load_config

    config = load_config(palaia_root)
    plugin_config = config.get("plugin_config")

    # Only relevant if plugin_config exists (user ran init --capture-level or
    # had explicit settings). If no plugin_config at all, the TypeScript plugin
    # defaults apply (which are already v2.0 defaults after this release).
    if not plugin_config:
        return {
            "name": "plugin_defaults_upgrade",
            "label": "Plugin defaults",
            "status": "ok",
            "message": "Using plugin defaults (v2.0)",
        }

    # Detect v1.x default values that need upgrading.
    # Only suggest upgrade for values that match the OLD defaults exactly —
    # if the user set custom values, respect them.
    upgradeable: list[str] = []
    # autoCapture: false → true (only if user has the old default)
    if plugin_config.get("autoCapture") is False:
        upgradeable.append("autoCapture: false → true")
    # memoryInject: false → true (only if user has the old default)
    if plugin_config.get("memoryInject") is False:
        upgradeable.append("memoryInject: false → true")
    # maxInjectedChars: 4000 → 8000 (only if user has the old default)
    if plugin_config.get("maxInjectedChars") == 4000:
        upgradeable.append("maxInjectedChars: 4000 → 8000")
    # recallMode: list → query (only if user has the old default)
    if plugin_config.get("recallMode") == "list":
        upgradeable.append("recallMode: list → query")
    # showMemorySources: false → true (v2.0 transparency feature, default is true)
    if plugin_config.get("showMemorySources") is False:
        upgradeable.append("showMemorySources: false → true")
    # showCaptureConfirm: false → true (v2.0 transparency feature, default is true)
    if plugin_config.get("showCaptureConfirm") is False:
        upgradeable.append("showCaptureConfirm: false → true")
    # captureMinSignificance: old value > 0.5 → 0.3 (v2.0 default is 0.3 — more inclusive)
    min_sig = plugin_config.get("captureMinSignificance")
    if isinstance(min_sig, (int, float)) and min_sig > 0.5:
        upgradeable.append(f"captureMinSignificance: {min_sig} → 0.3")

    if not upgradeable:
        return {
            "name": "plugin_defaults_upgrade",
            "label": "Plugin defaults",
            "status": "ok",
            "message": "Plugin config is up to date",
        }

    changes_summary = ", ".join(upgradeable)
    return {
        "name": "plugin_defaults_upgrade",
        "label": "Plugin defaults",
        "status": "warn",
        "message": f"v1.x defaults detected: {changes_summary}",
        "fix": (
            "Palaia 2.0 has optimized defaults for zero-config UX.\n"
            f"  Run: palaia doctor --fix  to upgrade your config.\n"
            f"  Changes: {changes_summary}\n"
            "  Custom values you've set will NOT be touched."
        ),
        "fixable": True,
        "details": {"upgradeable": upgradeable},
    }


def _check_capture_level(palaia_root: Path | None) -> dict[str, Any]:
    """Check if capture-level is configured in an OpenClaw environment (Issue #67)."""
    if palaia_root is None:
        return {
            "name": "capture_level",
            "label": "Capture level",
            "status": "info",
            "message": "Not initialized",
        }

    from palaia.config import load_config

    config = load_config(palaia_root)
    plugin_config = config.get("plugin_config")

    # Only relevant in OpenClaw environments
    import os

    is_openclaw = (Path.home() / ".openclaw").is_dir() or bool(os.environ.get("OPENCLAW_HOME"))

    if not is_openclaw:
        return {
            "name": "capture_level",
            "label": "Capture level",
            "status": "ok",
            "message": "Not an OpenClaw environment (skipped)",
        }

    if plugin_config and "autoCapture" in plugin_config:
        auto = plugin_config.get("autoCapture", False)
        if auto:
            freq = plugin_config.get("captureFrequency", "significant")
            turns = plugin_config.get("captureMinTurns", 2)
            return {
                "name": "capture_level",
                "label": "Capture level",
                "status": "ok",
                "message": f"autoCapture=true, frequency={freq}, minTurns={turns}",
            }
        else:
            return {
                "name": "capture_level",
                "label": "Capture level",
                "status": "ok",
                "message": "autoCapture=off",
            }

    return {
        "name": "capture_level",
        "label": "Capture level",
        "status": "info",
        "message": "No capture level configured",
        "fix": "Set capture level with: palaia init --capture-level <off|sparsam|normal|aggressiv>\n"
        "  Recommended: palaia init --capture-level normal",
    }


def _check_capture_model() -> dict[str, Any]:
    """Check if captureModel is configured when autoCapture is active."""
    import os as _os

    from palaia.config import VPS_OPENCLAW_BASE

    _home = Path.home()
    _base_dirs = [_home / ".openclaw"]
    if VPS_OPENCLAW_BASE != _home / ".openclaw" and VPS_OPENCLAW_BASE.is_dir():
        _base_dirs.append(VPS_OPENCLAW_BASE)

    config_candidates: list[Path] = []
    for base in _base_dirs:
        config_candidates.extend(
            [
                base / "openclaw.json",
                base / "openclaw.yaml",
                base / "openclaw.yml",
                base / "config.json",
                base / "config.yaml",
                base / "config.yml",
            ]
        )

    env_config = _os.environ.get("OPENCLAW_CONFIG")
    if env_config:
        env_path = Path(env_config)
        if env_path not in config_candidates:
            config_candidates.insert(0, env_path)

    for config_path in config_candidates:
        if not config_path.exists():
            continue

        try:
            if config_path.suffix == ".json":
                with open(config_path) as f:
                    oc_config = json.load(f)
            elif config_path.suffix in (".yaml", ".yml"):
                try:
                    import yaml  # type: ignore[import-untyped]

                    with open(config_path) as f:
                        oc_config = yaml.safe_load(f)
                except ImportError:
                    continue
            else:
                continue

            # Check if palaia plugin is active
            plugins = oc_config.get("plugins", {})
            slots = plugins.get("slots", {})
            memory_plugin = slots.get("memory")

            if memory_plugin != "palaia":
                continue

            # Get palaia plugin config
            entries = plugins.get("entries", {})
            palaia_entry = entries.get("palaia", {})
            palaia_config = palaia_entry.get("config", {})

            # autoCapture defaults to true
            auto_capture = palaia_config.get("autoCapture", True)
            if not auto_capture:
                return {
                    "name": "capture_model",
                    "label": "Capture model",
                    "status": "ok",
                    "message": "autoCapture is off (captureModel not needed)",
                }

            capture_model = palaia_config.get("captureModel")
            if capture_model:
                # Validate that the provider has an auth profile configured
                provider_name = capture_model.split("/")[0] if "/" in capture_model else None
                if provider_name:
                    auth_profiles = oc_config.get("auth", {}).get("profiles", {})
                    # Check if any auth profile matches the provider
                    provider_has_auth = any(
                        provider_name.lower() in str(profile_key).lower()
                        or provider_name.lower() in str(profile_val).lower()
                        for profile_key, profile_val in (
                            auth_profiles.items() if isinstance(auth_profiles, dict) else []
                        )
                    )
                    # Also check for provider-specific env vars or top-level auth keys
                    provider_auth_keys = oc_config.get("auth", {})
                    has_provider_section = provider_name.lower() in str(provider_auth_keys).lower()

                    if not provider_has_auth and not has_provider_section:
                        return {
                            "name": "capture_model",
                            "label": "Capture model",
                            "status": "warn",
                            "message": (
                                f"captureModel provider '{provider_name}' has no auth profile "
                                "configured — capture may fail"
                            ),
                            "details": {
                                "captureModel": capture_model,
                                "provider": provider_name,
                            },
                        }

                return {
                    "name": "capture_model",
                    "label": "Capture model",
                    "status": "ok",
                    "message": f"captureModel: {capture_model}",
                }

            return {
                "name": "capture_model",
                "label": "Capture model",
                "status": "info",
                "message": (
                    "No captureModel set — using primary model. "
                    "Consider setting a cheaper model (e.g. claude-haiku-4-5) "
                    "in openclaw.json \u2192 plugins.entries.palaia.config.captureModel"
                ),
            }
        except (json.JSONDecodeError, OSError, KeyError):
            continue

    return {
        "name": "capture_model",
        "label": "Capture model",
        "status": "ok",
        "message": "OpenClaw/Palaia plugin not detected (skipped)",
    }


def _check_embedding_model_integrity(palaia_root: Path | None) -> dict[str, Any]:
    """Check fastembed model cache integrity (corrupted symlinks cause ONNX errors)."""
    if palaia_root is None:
        return {
            "name": "embedding_model_integrity",
            "label": "Embedding model integrity",
            "status": "ok",
            "message": "Not initialized",
        }

    from palaia.config import load_config

    config = load_config(palaia_root)
    chain = config.get("embedding_chain", [])

    if "fastembed" not in chain:
        return {
            "name": "embedding_model_integrity",
            "label": "Embedding model integrity",
            "status": "ok",
            "message": "fastembed not in chain (skipped)",
        }

    # Resolve model name from config
    models = config.get("embedding_models", {})
    model_name = models.get("fastembed", "BAAI/bge-small-en-v1.5")

    # Convert model name to cache dir name: BAAI/bge-small-en-v1.5 → qdrant--bge-small-en-v1.5-onnx-q
    # fastembed uses qdrant HF repos with -onnx-q suffix
    model_short = model_name.split("/")[-1] if "/" in model_name else model_name
    cache_dir_name = f"models--qdrant--{model_short}-onnx-q"
    import tempfile

    cache_base = Path(tempfile.gettempdir()) / "fastembed_cache"
    cache_dir = cache_base / cache_dir_name

    if not cache_dir.exists():
        # Not cached yet — warmup will download it
        return {
            "name": "embedding_model_integrity",
            "label": "Embedding model integrity",
            "status": "ok",
            "message": "Cache not present yet (run: palaia warmup)",
        }

    # Look for ONNX model file in the cache
    onnx_files = list(cache_dir.rglob("model_optimized.onnx")) + list(cache_dir.rglob("model.onnx"))

    if not onnx_files:
        return {
            "name": "embedding_model_integrity",
            "label": "Embedding model integrity",
            "status": "warn",
            "message": "fastembed model cache is corrupted (no ONNX file found). Run: palaia doctor --fix",
            "fixable": True,
            "details": {"cache_dir": str(cache_dir), "model": model_name},
        }

    # Check each ONNX file: must be a real file, not a broken symlink
    for onnx_file in onnx_files:
        if onnx_file.is_symlink():
            target = onnx_file.resolve()
            if not target.exists():
                return {
                    "name": "embedding_model_integrity",
                    "label": "Embedding model integrity",
                    "status": "warn",
                    "message": "fastembed model cache is corrupted (broken symlink). Run: palaia doctor --fix",
                    "fixable": True,
                    "details": {
                        "cache_dir": str(cache_dir),
                        "broken_file": str(onnx_file),
                        "model": model_name,
                    },
                }
        elif not onnx_file.is_file():
            return {
                "name": "embedding_model_integrity",
                "label": "Embedding model integrity",
                "status": "warn",
                "message": "fastembed model cache is corrupted. Run: palaia doctor --fix",
                "fixable": True,
                "details": {"cache_dir": str(cache_dir), "model": model_name},
            }

    return {
        "name": "embedding_model_integrity",
        "label": "Embedding model integrity",
        "status": "ok",
        "message": f"Cache OK ({model_short})",
        "details": {"cache_dir": str(cache_dir), "model": model_name},
    }


def _check_index_staleness(palaia_root: Path | None) -> dict[str, Any]:
    """Check if embedding index is stale (entries missing from cache)."""
    if palaia_root is None:
        return {
            "name": "index_staleness",
            "label": "Embedding index",
            "status": "error",
            "message": "Not initialized",
        }

    from palaia.config import load_config
    from palaia.embeddings import BM25Provider, build_embedding_chain
    from palaia.index import EmbeddingCache

    config = load_config(palaia_root)
    chain = build_embedding_chain(config)

    # Skip check if BM25-only (no semantic embeddings configured)
    has_semantic = any(not isinstance(p, BM25Provider) for p in chain.providers)
    if not has_semantic:
        return {
            "name": "index_staleness",
            "label": "Embedding index",
            "status": "ok",
            "message": "BM25-only (no semantic index needed)",
        }

    # Count entries across hot+warm
    total_entries = 0
    for tier in ("hot", "warm"):
        tier_dir = palaia_root / tier
        if tier_dir.exists():
            total_entries += sum(1 for _ in tier_dir.glob("*.md"))

    if total_entries == 0:
        return {
            "name": "index_staleness",
            "label": "Embedding index",
            "status": "ok",
            "message": "No entries to index",
        }

    cache = EmbeddingCache(palaia_root)
    cache_stats = cache.stats()
    cached_count = cache_stats.get("cached_entries", 0)
    missing = total_entries - cached_count

    if missing <= 0:
        return {
            "name": "index_staleness",
            "label": "Embedding index",
            "status": "ok",
            "message": f"{cached_count}/{total_entries} entries indexed",
            "details": {"total": total_entries, "cached": cached_count},
        }

    pct_missing = missing / total_entries
    if pct_missing > 0.1:
        return {
            "name": "index_staleness",
            "label": "Embedding index",
            "status": "warn",
            "message": f"{missing} entries not indexed. Semantic search quality degraded.",
            "fix": "Run: palaia warmup",
            "fixable": True,
            "details": {"total": total_entries, "cached": cached_count, "missing": missing},
        }

    return {
        "name": "index_staleness",
        "label": "Embedding index",
        "status": "ok",
        "message": f"{cached_count}/{total_entries} entries indexed ({missing} pending)",
        "details": {"total": total_entries, "cached": cached_count, "missing": missing},
    }


def run_doctor(palaia_root: Path | None = None) -> list[dict[str, Any]]:
    """Run all doctor checks. Returns list of check results."""
    results = [
        _check_palaia_init(palaia_root),
        _check_agent_identity(palaia_root),
        _check_multi_agent_static(palaia_root),
        _check_store_version(palaia_root),
        _check_version_available(palaia_root),
        _check_embedding_chain(palaia_root),
        _check_embedding_model_integrity(palaia_root),
        _check_index_staleness(palaia_root),
        _check_entry_classes(palaia_root),
        _check_projects_usage(palaia_root),
        _check_deprecated_config(palaia_root),
        _check_default_agent_alias(palaia_root),
        _check_unread_memos(palaia_root),
        _check_capture_level(palaia_root),
        _check_capture_model(),
        _check_plugin_defaults_upgrade(palaia_root),
        _check_openclaw_plugin(),
        _check_smart_memory_skill(),
        _check_legacy_memory_files(),
        _check_heartbeat_legacy(),
        _check_wal_health(palaia_root),
        _check_loop_artifacts(palaia_root),
    ]
    return results


def apply_fixes(palaia_root: Path | None, results: list[dict[str, Any]]) -> list[str]:
    """Apply automatic fixes for fixable warnings. Returns list of actions taken."""
    actions: list[str] = []
    if palaia_root is None:
        return actions

    from palaia.config import load_config, save_config
    from palaia.embeddings import detect_providers

    config = load_config(palaia_root)
    ran_warmup = False

    for r in results:
        if r.get("status") != "warn":
            continue

        # Fix: embedding chain has missing providers
        if r.get("name") == "embedding_chain" and r.get("fixable"):
            missing = r.get("details", {}).get("missing", [])
            old_chain = config.get("embedding_chain", [])

            # Guard: respect explicit user embedding config (#57)
            # If embedding_provider is explicitly set (not "auto") and the
            # provider is still available, do NOT touch the chain or provider.
            explicit_provider = config.get("embedding_provider", "auto")
            if explicit_provider and explicit_provider != "auto":
                detected_guard = detect_providers()
                detected_guard_map = {p["name"]: p["available"] for p in detected_guard}
                if detected_guard_map.get(explicit_provider, False):
                    # Explicit provider is still functional — preserve config.
                    # Only remove broken providers from chain, keep the rest.
                    new_chain = [p for p in old_chain if p == "bm25" or detected_guard_map.get(p, False)]
                    if not new_chain or new_chain == ["bm25"]:
                        # At minimum, keep the explicit provider + bm25
                        new_chain = [explicit_provider, "bm25"]
                    elif "bm25" not in new_chain:
                        new_chain.append("bm25")

                    if new_chain != old_chain:
                        config["embedding_chain"] = new_chain
                        save_config(palaia_root, config)
                        chain_str = " → ".join(new_chain)
                        actions.append(f"Cleaned chain (kept explicit provider {explicit_provider}): {chain_str}")
                    else:
                        actions.append(f"Explicit provider {explicit_provider} is available — config unchanged")
                    # Still need warmup if semantic providers present
                    if any(p != "bm25" for p in new_chain):
                        ran_warmup = True
                    continue

            installed_providers: list[str] = []

            # Step 1: Try to install missing providers via pip
            for provider_name in missing:
                install_cmd = _pip_install_cmd(provider_name)
                if install_cmd:
                    print(f"  Attempting: {install_cmd}")
                    success = _try_pip_install(install_cmd)
                    if success:
                        installed_providers.append(provider_name)
                        actions.append(f"Installed {provider_name}")
                        print(f"  Installed {provider_name} successfully.")
                    else:
                        print(f"  Could not install {provider_name}.")

            # Step 2: Re-detect providers after installation attempts
            detected = detect_providers()
            detected_map = {p["name"]: p["available"] for p in detected}

            # Step 3: Build new chain — keep available providers from old chain
            # preserving original order (user's preference)
            new_chain = [p for p in old_chain if p == "bm25" or detected_map.get(p, False)]

            # If chain is empty or only bm25, build best available chain
            # _build_best_chain() only as last resort when NO valid chain exists
            if not new_chain or new_chain == ["bm25"]:
                new_chain = _build_best_chain(detected)

            if "bm25" not in new_chain:
                new_chain.append("bm25")

            config["embedding_chain"] = new_chain
            save_config(palaia_root, config)

            chain_str = " → ".join(new_chain)
            if installed_providers:
                actions.append(f"Chain: {chain_str}")
            else:
                still_missing = [p for p in missing if not detected_map.get(p, False)]
                if still_missing:
                    actions.append(f"{', '.join(still_missing)} not available, chain updated to {chain_str}")
                else:
                    actions.append(f"Updated embedding chain: {chain_str}")

            # Step 4: Run warmup to download models
            if any(p != "bm25" for p in new_chain):
                ran_warmup = True

        # Fix: no chain configured → auto-detect and set
        if r.get("name") == "embedding_chain" and r.get("fixable") and not r.get("details", {}).get("missing"):
            # Guard: if explicit provider is set and available, build chain around it
            explicit_provider = config.get("embedding_provider", "auto")
            detected = detect_providers()
            detected_map = {p["name"]: p["available"] for p in detected}

            if explicit_provider and explicit_provider != "auto" and detected_map.get(explicit_provider, False):
                new_chain = [explicit_provider, "bm25"]
            else:
                new_chain = _build_best_chain(detected)

            config["embedding_chain"] = new_chain
            save_config(palaia_root, config)
            actions.append(f"Auto-configured chain: {' → '.join(new_chain)}")
            if any(p != "bm25" for p in new_chain):
                ran_warmup = True

    # Fix: stale embedding index
    for r in results:
        if r.get("name") == "index_staleness" and r.get("fixable") and r.get("status") == "warn":
            try:
                from palaia.embed_server import _warmup_missing
                from palaia.search import SearchEngine
                from palaia.store import Store

                store = Store(palaia_root)
                engine = SearchEngine(store)
                print("  Indexing missing entries...")
                stats = _warmup_missing(store, engine)
                new_count = stats.get("new", 0)
                if new_count > 0:
                    actions.append(f"Indexed {new_count} missing entries")
                else:
                    actions.append("Index is up to date")
            except Exception as e:
                actions.append(f"Index warmup failed: {e}")

    # Fix: corrupted fastembed cache
    for r in results:
        if r.get("name") == "embedding_model_integrity" and r.get("fixable") and r.get("status") == "warn":
            cache_dir = r.get("details", {}).get("cache_dir")
            if cache_dir:
                import shutil

                cache_path = Path(cache_dir)
                if cache_path.exists():
                    try:
                        shutil.rmtree(cache_path)
                        actions.append(f"Removed corrupted fastembed cache: {cache_dir}")
                        ran_warmup = True  # warmup will re-download
                    except OSError as e:
                        actions.append(f"Failed to remove corrupted cache: {e}")

    # Fix: upgrade v1.x plugin defaults to v2.0
    for r in results:
        if r.get("name") == "plugin_defaults_upgrade" and r.get("fixable") and r.get("status") == "warn":
            plugin_config = config.get("plugin_config", {})
            upgraded = []

            # Only upgrade values that match old v1.x defaults exactly
            if plugin_config.get("autoCapture") is False:
                plugin_config["autoCapture"] = True
                upgraded.append("autoCapture: false → true")
            if plugin_config.get("memoryInject") is False:
                plugin_config["memoryInject"] = True
                upgraded.append("memoryInject: false → true")
            if plugin_config.get("maxInjectedChars") == 4000:
                plugin_config["maxInjectedChars"] = 8000
                upgraded.append("maxInjectedChars: 4000 → 8000")
            if plugin_config.get("recallMode") == "list":
                plugin_config["recallMode"] = "query"
                upgraded.append("recallMode: list → query")
            if plugin_config.get("showMemorySources") is False:
                plugin_config["showMemorySources"] = True
                upgraded.append("showMemorySources: false → true")
            if plugin_config.get("showCaptureConfirm") is False:
                plugin_config["showCaptureConfirm"] = True
                upgraded.append("showCaptureConfirm: false → true")
            min_sig = plugin_config.get("captureMinSignificance")
            if isinstance(min_sig, (int, float)) and min_sig > 0.5:
                plugin_config["captureMinSignificance"] = 0.3
                upgraded.append(f"captureMinSignificance: {min_sig} → 0.3")

            if upgraded:
                config["plugin_config"] = plugin_config
                save_config(palaia_root, config)
                actions.append(f"Upgraded plugin defaults to v2.0: {', '.join(upgraded)}")

    # Run warmup + reindex after all fixes if we have semantic providers
    if ran_warmup:
        try:
            from palaia.embeddings import warmup_providers

            print("  Running warmup to pre-download models...")
            warmup_results = warmup_providers(config)
            for wr in warmup_results:
                status_label = "ok" if wr["status"] == "ready" else wr["status"]
                print(f"    [{status_label}] {wr['name']}: {wr['message']}")
            actions.append("Warmup complete")

            # Reindex entries to fill embedding cache
            try:
                from palaia.cli import _reindex_entries

                class _FakeArgs:
                    json = False

                print("  Building embedding index...")
                index_stats = _reindex_entries(palaia_root, config, _FakeArgs())
                if index_stats.get("new", 0) > 0:
                    actions.append(
                        f"Indexed {index_stats['indexed']} entries "
                        f"({index_stats['new']} new, {index_stats['cached']} cached)"
                    )
            except Exception as e:
                actions.append(f"Reindex failed: {e}")
        except Exception as e:
            actions.append(f"Warmup failed: {e}")

    # Fix: feedback-loop artifacts
    for r in results:
        if r.get("name") == "loop_artifacts" and r.get("fixable") and r.get("status") == "warn":
            artifact_ids = r.get("details", {}).get("artifact_ids", [])
            if not artifact_ids:
                continue

            from palaia.entry import parse_entry, serialize_entry

            cleaned = 0
            for entry_id in artifact_ids:
                # Find the entry file across tiers
                for tier in ("hot", "warm", "cold"):
                    entry_path = palaia_root / tier / f"{entry_id}.md"
                    if entry_path.exists():
                        try:
                            text = entry_path.read_text(encoding="utf-8")
                            meta, body = parse_entry(text)
                            meta["status"] = "done"
                            if meta.get("type") != "memory":
                                meta["type"] = "memory"
                            entry_path.write_text(serialize_entry(meta, body), encoding="utf-8")
                            cleaned += 1
                        except Exception as e:
                            actions.append(f"Failed to clean {entry_id}: {e}")
                        break

            if cleaned > 0:
                actions.append(f"Cleaned {cleaned} feedback-loop artifact(s)")

    return actions


def _pip_install_cmd(provider_name: str) -> str | None:
    """Return the pip install command for a provider, or None if not pip-installable."""
    install_map = {
        "sentence-transformers": 'pip install "palaia[sentence-transformers]"',
        "fastembed": 'pip install "palaia[fastembed]"',
    }
    return install_map.get(provider_name)


def _try_pip_install(cmd: str) -> bool:
    """Try to run a pip install command. Returns True on success."""
    import subprocess
    import sys

    # Extract package spec from the command (e.g. 'pip install "palaia[st]"' -> 'palaia[st]')
    parts = cmd.split()
    if len(parts) < 3:
        return False
    # Use the current Python interpreter's pip to ensure correct environment
    pkg = parts[2].strip('"').strip("'")
    try:
        result = subprocess.run(
            [sys.executable, "-m", "pip", "install", pkg],
            capture_output=True,
            text=True,
            timeout=300,
        )
        return result.returncode == 0
    except (subprocess.TimeoutExpired, OSError):
        return False


def _build_best_chain(detected: list[dict[str, Any]]) -> list[str]:
    """Build the best available embedding chain from detected providers.

    Prefers semantic providers. BM25-only is the last resort.
    Priority: openai > sentence-transformers > fastembed > ollama > bm25
    """
    chain: list[str] = []
    priority_order = ["openai", "sentence-transformers", "fastembed", "ollama"]
    detected_map = {p["name"]: p["available"] for p in detected}

    for name in priority_order:
        if detected_map.get(name, False):
            chain.append(name)

    chain.append("bm25")
    return chain


def format_doctor_report(results: list[dict[str, Any]], show_fix: bool = False) -> str:
    """Format doctor results as a human-readable report using box-drawing tables."""
    from palaia.ui import header, section, table_multi

    lines = [header()]
    lines.append(section("Health Report"))

    # Build table rows
    table_rows = []
    warnings = 0
    errors = 0

    for r in results:
        status = r["status"]
        label = r["label"]
        message = r["message"]
        status_str = f"[{status}]"
        table_rows.append((status_str, label, message))

        if status == "warn":
            warnings += 1
        elif status == "error":
            errors += 1

    lines.append(
        table_multi(
            headers=("Status", "Check", "Details"),
            rows=table_rows,
            min_widths=(8, 22, 30),
        )
    )

    # Show fix details below table if requested
    if show_fix:
        fix_lines = []
        for r in results:
            if r["status"] == "warn" and "fix" in r:
                fix_lines.append(f"\n  {r['label']}:")
                for fl in r["fix"].split("\n"):
                    fix_lines.append(f"    {fl}")
        if fix_lines:
            lines.append("\nFix guidance:")
            lines.extend(fix_lines)
    else:
        # Show inline fix hints for warnings
        for r in results:
            if r["status"] == "warn" and "fix" in r:
                first_fix = r["fix"].split("\n")[0]
                lines.append(f"  {r['label']}: {first_fix}")

    # Summary
    if errors:
        lines.append(f"\nErrors: {errors} — fix before using Palaia")
    elif warnings:
        suffix = " — see fixes above" if show_fix else " — run with --fix for guided cleanup"
        lines.append(f"\nAction required: {warnings} warning(s){suffix}")
    else:
        lines.append("\nAll clear. Palaia is healthy.")

    return "\n".join(lines)

"""Embedding server — long-lived subprocess for fast semantic search.

Loads the embedding model once and serves queries over stdin/stdout JSON-RPC.
Eliminates the ~3-23s model loading penalty on every CLI invocation.

Usage:
    palaia embed-server

Protocol: One JSON object per line on stdin/stdout.
Requests:
    {"method": "query", "params": {"text": "...", "top_k": 10, "agent": "...", "project": "...", "scope": "..."}}
    {"method": "warmup"}
    {"method": "ping"}
    {"method": "status"}
    {"method": "shutdown"}
"""

from __future__ import annotations

import json
import sys
import threading
import time
import traceback
from pathlib import Path

from palaia.config import get_root
from palaia.embeddings import BM25Provider
from palaia.search import SearchEngine
from palaia.store import Store


def _count_entries(store: Store) -> int:
    """Count total entries across hot+warm tiers (fast, no parsing)."""
    count = 0
    for tier in ("hot", "warm"):
        tier_dir = store.root / tier
        if tier_dir.exists():
            count += sum(1 for _ in tier_dir.glob("*.md"))
    return count


def _warmup_missing(store: Store, engine: SearchEngine) -> dict:
    """Index any entries missing from the embedding cache. Returns stats."""
    provider = engine.provider
    if isinstance(provider, BM25Provider):
        return {"indexed": 0, "new": 0, "cached": 0}

    entries = store.all_entries_unfiltered(include_cold=False)
    total = len(entries)
    if total == 0:
        return {"indexed": 0, "new": 0, "cached": 0}

    uncached = []
    cached_count = 0
    for meta, body, _tier in entries:
        entry_id = meta.get("id", "")
        if not entry_id:
            continue
        if store.embedding_cache.get_cached(entry_id) is not None:
            cached_count += 1
        else:
            title = meta.get("title", "")
            tags = " ".join(meta.get("tags", []))
            full_text = f"{title} {tags} {body}"
            uncached.append((entry_id, full_text))

    if not uncached:
        return {"indexed": total, "new": 0, "cached": cached_count}

    model_name = getattr(provider, "model_name", None) or getattr(provider, "model", "unknown")
    new_count = 0
    batch_size = 32

    for i in range(0, len(uncached), batch_size):
        batch = uncached[i : i + batch_size]
        texts = [text for _, text in batch]
        ids = [eid for eid, _ in batch]
        try:
            vectors = provider.embed(texts)
            for eid, vec in zip(ids, vectors):
                store.embedding_cache.set_cached(eid, vec, model=model_name)
                new_count += 1
        except Exception:
            break

    return {"indexed": cached_count + new_count, "new": new_count, "cached": cached_count}


class EmbedServer:
    """JSON-RPC server over stdin/stdout for embedding queries."""

    def __init__(self, root: Path):
        self.root = root
        self.store = Store(root)
        self.engine = SearchEngine(self.store)
        # BM25-only fallback engine for queries during warmup (no GIL contention)
        self._bm25_engine = SearchEngine(self.store)
        self._bm25_engine._provider = BM25Provider()
        self._last_entry_count = _count_entries(self.store)
        self._running = True
        self._warming_up = False
        self._stale_check_thread: threading.Thread | None = None

    def _start_stale_detection(self) -> None:
        """Start background thread that checks for entry count changes every 30s."""

        def _check_loop():
            while self._running:
                time.sleep(30)
                if not self._running:
                    break
                try:
                    current = _count_entries(self.store)
                    if current != self._last_entry_count:
                        self._last_entry_count = current
                        # Force BM25 index rebuild on next query by resetting the engine
                        self.engine = SearchEngine(self.store)
                        # Reload embedding cache from disk
                        self.store.embedding_cache._cache = None
                except Exception:
                    pass

        self._stale_check_thread = threading.Thread(target=_check_loop, daemon=True)
        self._stale_check_thread.start()

    def handle_request(self, request: dict) -> dict:
        """Dispatch a single JSON-RPC request. Always returns a dict."""
        method = request.get("method", "")

        if method == "ping":
            return {"result": "pong"}

        if method == "shutdown":
            self._running = False
            return {"result": "shutting_down"}

        if method == "status":
            return self._handle_status()

        if method == "warmup":
            return self._handle_warmup()

        if method == "query":
            return self._handle_query(request.get("params", {}))

        return {"error": f"Unknown method: {method}"}

    def _handle_status(self) -> dict:
        """Return entry count, cache coverage, and provider info."""
        entries = _count_entries(self.store)
        cache_stats = self.store.embedding_cache.stats()
        provider = self.engine.provider
        provider_name = getattr(provider, "name", "unknown")
        model = getattr(provider, "model_name", None) or getattr(provider, "model", None) or ""
        return {
            "result": {
                "entries": entries,
                "cached": cache_stats.get("cached_entries", 0),
                "provider": provider_name,
                "model": model,
                "has_embeddings": self.engine.has_embeddings,
                "warming_up": self._warming_up,
            }
        }

    def _handle_warmup(self) -> dict:
        """Index all missing entries."""
        stats = _warmup_missing(self.store, self.engine)
        return {"result": stats}

    def _handle_query(self, params: dict) -> dict:
        """Execute a search query using the existing SearchEngine."""
        text = params.get("text", "")
        if not text:
            return {"error": "Missing 'text' parameter"}

        top_k = params.get("top_k", 10)
        agent = params.get("agent")
        project = params.get("project")
        _scope = params.get("scope")  # reserved for future scope filtering
        entry_type = params.get("type")
        status = params.get("status")
        priority = params.get("priority")
        assignee = params.get("assignee")
        instance = params.get("instance")
        include_cold = params.get("include_cold", False)
        cross_project = params.get("cross_project", False)

        engine = self._bm25_engine if self._warming_up else self.engine
        results = engine.search(
            text,
            top_k=top_k,
            include_cold=include_cold,
            project=project,
            agent=agent,
            entry_type=entry_type,
            status=status,
            priority=priority,
            assignee=assignee,
            instance=instance,
            cross_project=cross_project,
        )

        return {"result": {"results": results}}

    def run(self) -> None:
        """Main loop: read JSON lines from stdin, write JSON responses to stdout."""
        # Start stale detection
        self._start_stale_detection()

        # Signal ready IMMEDIATELY — warmup runs in background
        # Queries arriving during warmup use BM25 fallback automatically
        self._warming_up = True
        self._write_response({"result": "ready"})

        # Background warmup thread
        def _bg_warmup():
            try:
                _warmup_missing(self.store, self.engine)
            except Exception:
                pass
            finally:
                self._warming_up = False

        warmup_thread = threading.Thread(target=_bg_warmup, daemon=True)
        warmup_thread.start()

        while self._running:
            try:
                line = sys.stdin.readline()
                if not line:
                    # EOF — parent process closed stdin
                    break
                line = line.strip()
                if not line:
                    continue

                try:
                    request = json.loads(line)
                except json.JSONDecodeError as e:
                    self._write_response({"error": f"Invalid JSON: {e}"})
                    continue

                response = self.handle_request(request)
                self._write_response(response)

            except Exception as e:
                try:
                    self._write_response({"error": f"Internal error: {e}", "traceback": traceback.format_exc()})
                except Exception:
                    break

    def _write_response(self, response: dict) -> None:
        """Write a JSON response line to stdout."""
        sys.stdout.write(json.dumps(response, ensure_ascii=False) + "\n")
        sys.stdout.flush()


def main() -> None:
    """Entry point for `palaia embed-server`."""
    root = get_root()
    server = EmbedServer(root)
    server.run()


if __name__ == "__main__":
    main()

"""Multi-provider embedding support for semantic search.

Providers are detected automatically in this order:
1. ollama (local server with nomic-embed-text)
2. sentence-transformers (pure Python)
3. fastembed (lightweight)
4. OpenAI API (cloud, needs OPENAI_API_KEY)
5. Gemini API (cloud, needs GEMINI_API_KEY)
6. BM25 (always available, keyword-based fallback)

Embedding Chain:
  A configurable fallback chain lets you define a priority list of providers.
  Palaia tries the first provider; if it fails (rate-limit, timeout, import error),
  it moves to the next. BM25 is always the last resort.
"""

from __future__ import annotations

import importlib.metadata as _importlib_metadata
import importlib.util
import math
import os
import re
import warnings
from collections import Counter
from typing import Protocol, runtime_checkable


@runtime_checkable
class EmbeddingProvider(Protocol):
    """Protocol for embedding providers."""

    name: str

    def embed(self, texts: list[str]) -> list[list[float]]:
        """Embed a batch of texts. Returns list of vectors."""
        ...

    def embed_query(self, text: str) -> list[float]:
        """Embed a single query text. Returns a vector."""
        ...


class OllamaProvider:
    """Embedding via local ollama server."""

    name = "ollama"
    default_model = "nomic-embed-text"

    def __init__(self, model: str | None = None, base_url: str = "http://localhost:11434"):
        self.model = model or self.default_model
        self.base_url = base_url
        self._client = None

    def _get_client(self):
        if self._client is None:
            try:
                import ollama as ollama_lib

                self._client = ollama_lib.Client(host=self.base_url)
            except ImportError:
                # Fall back to raw HTTP
                self._client = "http"
        return self._client

    def embed(self, texts: list[str]) -> list[list[float]]:
        client = self._get_client()
        if client == "http":
            return [self._embed_http(t) for t in texts]
        results = []
        for text in texts:
            resp = client.embed(model=self.model, input=text)
            # ollama returns {"embeddings": [[...]]}
            if isinstance(resp, dict) and "embeddings" in resp:
                results.append(resp["embeddings"][0])
            else:
                results.append(resp.embeddings[0] if hasattr(resp, "embeddings") else [])
        return results

    def embed_query(self, text: str) -> list[float]:
        return self.embed([text])[0]

    def _embed_http(self, text: str) -> list[float]:
        import json
        import urllib.request

        data = json.dumps({"model": self.model, "input": text}).encode()
        req = urllib.request.Request(
            f"{self.base_url}/api/embed",
            data=data,
            headers={"Content-Type": "application/json"},
        )
        with urllib.request.urlopen(req, timeout=30) as resp:
            result = json.loads(resp.read())
        return result.get("embeddings", [[]])[0]


class SentenceTransformersProvider:
    """Embedding via sentence-transformers library."""

    name = "sentence-transformers"
    default_model = "all-MiniLM-L6-v2"

    def __init__(self, model: str | None = None):
        self.model_name = model or self.default_model
        self._model = None

    def _get_model(self):
        if self._model is None:
            import io
            import logging
            import os
            import sys

            # Suppress noisy HuggingFace / tokenizers / safetensors warnings
            os.environ.setdefault("TOKENIZERS_PARALLELISM", "false")
            os.environ.setdefault("HF_HUB_DISABLE_TELEMETRY", "1")
            os.environ.setdefault("HF_HUB_DISABLE_IMPLICIT_TOKEN", "1")
            os.environ.setdefault("HF_HUB_DISABLE_PROGRESS_BARS", "1")
            for _logger_name in (
                "sentence_transformers",
                "transformers",
                "huggingface_hub",
                "torch",
                "safetensors",
            ):
                logging.getLogger(_logger_name).setLevel(logging.ERROR)

            # Redirect stderr during import + model load to suppress safetensors
            # LOAD REPORT and HF Hub auth warnings that bypass the logging framework
            _old_stderr = sys.stderr
            sys.stderr = io.StringIO()
            try:
                from sentence_transformers import SentenceTransformer

                self._model = SentenceTransformer(self.model_name)
            finally:
                sys.stderr = _old_stderr
        return self._model

    def embed(self, texts: list[str]) -> list[list[float]]:
        model = self._get_model()
        embeddings = model.encode(texts, convert_to_numpy=True)
        return [e.tolist() for e in embeddings]

    def embed_query(self, text: str) -> list[float]:
        return self.embed([text])[0]


class FastEmbedProvider:
    """Embedding via fastembed library."""

    name = "fastembed"
    default_model = "BAAI/bge-small-en-v1.5"

    def __init__(self, model: str | None = None):
        self.model_name = model or self.default_model
        self._model = None

    def _get_model(self):
        if self._model is None:
            from fastembed import TextEmbedding

            self._model = TextEmbedding(model_name=self.model_name)
        return self._model

    def embed(self, texts: list[str]) -> list[list[float]]:
        model = self._get_model()
        embeddings = list(model.embed(texts))
        return [e.tolist() if hasattr(e, "tolist") else list(e) for e in embeddings]

    def embed_query(self, text: str) -> list[float]:
        return self.embed([text])[0]


class OpenAIProvider:
    """Embedding via OpenAI API."""

    name = "openai"
    default_model = "text-embedding-3-small"

    def __init__(self, model: str | None = None, api_key: str | None = None):
        self.model_name = model or self.default_model
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY", "")
        self._client = None

    def _get_client(self):
        if self._client is None:
            try:
                from openai import OpenAI

                self._client = OpenAI(api_key=self.api_key)
            except ImportError:
                self._client = "http"
        return self._client

    def embed(self, texts: list[str]) -> list[list[float]]:
        client = self._get_client()
        if client == "http":
            return self._embed_http(texts)
        resp = client.embeddings.create(model=self.model_name, input=texts)
        return [d.embedding for d in resp.data]

    def embed_query(self, text: str) -> list[float]:
        return self.embed([text])[0]

    def _embed_http(self, texts: list[str]) -> list[list[float]]:
        import json
        import urllib.request

        data = json.dumps({"model": self.model_name, "input": texts}).encode()
        req = urllib.request.Request(
            "https://api.openai.com/v1/embeddings",
            data=data,
            headers={
                "Content-Type": "application/json",
                "Authorization": f"Bearer {self.api_key}",
            },
        )
        with urllib.request.urlopen(req, timeout=30) as resp:
            result = json.loads(resp.read())
        return [d["embedding"] for d in result["data"]]


class GeminiProvider:
    """Embedding via Google Gemini API."""

    name = "gemini"
    default_model = "gemini-embedding-exp-03-07"

    def __init__(self, model: str | None = None, api_key: str | None = None):
        self.model_name = model or self.default_model
        self.api_key = api_key or os.environ.get("GEMINI_API_KEY", "")
        if not self.api_key:
            raise ValueError("GEMINI_API_KEY not set")

    def embed(self, texts: list[str]) -> list[list[float]]:
        """Embed texts via Gemini REST API."""
        import json
        import urllib.request

        results = []
        # Gemini embedContent accepts one text at a time; batch via batchEmbedContents
        url = f"https://generativelanguage.googleapis.com/v1beta/models/{self.model_name}:batchEmbedContents?key={self.api_key}"
        requests_body = [{"model": f"models/{self.model_name}", "content": {"parts": [{"text": t}]}} for t in texts]
        data = json.dumps({"requests": requests_body}).encode()
        req = urllib.request.Request(
            url,
            data=data,
            headers={"Content-Type": "application/json"},
        )
        with urllib.request.urlopen(req, timeout=30) as resp:
            result = json.loads(resp.read())
        for emb in result.get("embeddings", []):
            results.append(emb.get("values", []))
        return results

    def embed_query(self, text: str) -> list[float]:
        return self.embed([text])[0]


class BM25Provider:
    """Keyword-based search provider. Always available, no vectors."""

    name = "bm25"

    def __init__(self, k1: float = 1.5, b: float = 0.75):
        self.k1 = k1
        self.b = b
        self.corpus: list[tuple[str, list[str]]] = []
        self.doc_freqs: Counter = Counter()
        self.doc_lens: list[int] = []
        self.avg_dl: float = 0.0
        self.n_docs: int = 0

    def index(self, documents: list[tuple[str, str]]) -> None:
        """Index a list of (doc_id, text) tuples."""
        self.corpus = []
        self.doc_freqs = Counter()
        self.doc_lens = []

        for doc_id, text in documents:
            tokens = _tokenize(text)
            self.corpus.append((doc_id, tokens))
            self.doc_lens.append(len(tokens))
            seen = set(tokens)
            for t in seen:
                self.doc_freqs[t] += 1

        self.n_docs = len(self.corpus)
        self.avg_dl = sum(self.doc_lens) / self.n_docs if self.n_docs else 1.0

    def search(self, query: str, top_k: int = 10) -> list[tuple[str, float]]:
        """Search the index. Returns list of (doc_id, score) sorted desc."""
        query_tokens = _tokenize(query)
        if not query_tokens or not self.corpus:
            return []

        scores = []
        for idx, (doc_id, doc_tokens) in enumerate(self.corpus):
            score = 0.0
            dl = self.doc_lens[idx]
            tf_map = Counter(doc_tokens)

            for qt in query_tokens:
                if qt not in tf_map:
                    continue
                tf = tf_map[qt]
                df = self.doc_freqs.get(qt, 0)
                idf = math.log((self.n_docs - df + 0.5) / (df + 0.5) + 1.0)
                tf_norm = (tf * (self.k1 + 1)) / (tf + self.k1 * (1 - self.b + self.b * dl / self.avg_dl))
                score += idf * tf_norm

            if score > 0:
                scores.append((doc_id, score))

        scores.sort(key=lambda x: x[1], reverse=True)
        return scores[:top_k]

    def embed(self, texts: list[str]) -> list[list[float]]:
        """Not applicable for BM25. Raises NotImplementedError."""
        raise NotImplementedError("BM25 does not produce embedding vectors")

    def embed_query(self, text: str) -> list[float]:
        """Not applicable for BM25. Raises NotImplementedError."""
        raise NotImplementedError("BM25 does not produce embedding vectors")


def _tokenize(text: str) -> list[str]:
    """Simple whitespace + punctuation tokenizer."""
    text = text.lower()
    return re.findall(r"\b\w+\b", text)


def cosine_similarity(a: list[float], b: list[float]) -> float:
    """Compute cosine similarity between two vectors."""
    dot = sum(x * y for x, y in zip(a, b))
    norm_a = math.sqrt(sum(x * x for x in a))
    norm_b = math.sqrt(sum(x * x for x in b))
    if norm_a == 0 or norm_b == 0:
        return 0.0
    return dot / (norm_a * norm_b)


def _check_ollama_available(base_url: str = "http://localhost:11434") -> tuple[bool, str | None, list[str]]:
    """Check if ollama server is running and which models are available.

    Returns: (server_running, version_or_none, list_of_models)
    """
    import json
    import urllib.request

    try:
        req = urllib.request.Request(f"{base_url}/api/tags", method="GET")
        with urllib.request.urlopen(req, timeout=3) as resp:
            data = json.loads(resp.read())
        models = [m.get("name", "").split(":")[0] for m in data.get("models", [])]
        return True, None, models
    except Exception:
        return False, None, []


def _check_openai_key() -> str | None:
    """Check for OpenAI API key in env or openclaw auth."""
    key = os.environ.get("OPENAI_API_KEY")
    if key:
        return key
    # Check openclaw auth profiles
    auth_dir = os.path.expanduser("~/.openclaw")
    for candidate in ["auth.json", "config.json"]:
        path = os.path.join(auth_dir, candidate)
        if os.path.exists(path):
            try:
                import json

                with open(path) as f:
                    data = json.load(f)
                # Look for openai key in various formats
                if isinstance(data, dict):
                    if "openai_api_key" in data:
                        return data["openai_api_key"]
                    for profile in data.values():
                        if isinstance(profile, dict) and "openai_api_key" in profile:
                            return profile["openai_api_key"]
            except (OSError, ValueError):
                pass
    return None


def _check_gemini_key() -> str | None:
    """Check for Gemini API key in env."""
    return os.environ.get("GEMINI_API_KEY")


def _check_voyage_key() -> str | None:
    """Check for Voyage API key in env."""
    return os.environ.get("VOYAGE_API_KEY")


def detect_providers() -> list[dict]:
    """Detect all available embedding providers.

    Returns list of dicts with keys: name, available, version, models, install_hint
    """
    providers = []

    # 1. ollama
    server_running, version, models = _check_ollama_available()
    has_nomic = "nomic-embed-text" in models if models else False
    providers.append(
        {
            "name": "ollama",
            "available": server_running and has_nomic,
            "server_running": server_running,
            "models": models,
            "has_nomic": has_nomic,
            "version": version,
            "install_hint": None
            if server_running
            else "curl -fsSL https://ollama.com/install.sh | sh && ollama pull nomic-embed-text",
        }
    )

    # 2. sentence-transformers
    st_spec = importlib.util.find_spec("sentence_transformers")
    st_version = None
    if st_spec:
        try:
            # already imported as _importlib_metadata
            st_version = _importlib_metadata.version("sentence-transformers")
        except Exception:
            st_version = "installed"
    providers.append(
        {
            "name": "sentence-transformers",
            "available": st_spec is not None,
            "version": st_version,
            "install_hint": 'pip install "palaia[sentence-transformers]"' if not st_spec else None,
        }
    )

    # 3. fastembed
    fe_spec = importlib.util.find_spec("fastembed")
    fe_version = None
    if fe_spec:
        try:
            # already imported as _importlib_metadata
            fe_version = _importlib_metadata.version("fastembed")
        except Exception:
            fe_version = "installed"
    providers.append(
        {
            "name": "fastembed",
            "available": fe_spec is not None,
            "version": fe_version,
            "install_hint": 'pip install "palaia[fastembed]"' if not fe_spec else None,
        }
    )

    # 4. OpenAI
    openai_key = _check_openai_key()
    providers.append(
        {
            "name": "openai",
            "available": openai_key is not None,
            "version": None,
            "install_hint": None if openai_key else "Set OPENAI_API_KEY environment variable",
        }
    )

    # 5. Gemini
    gemini_key = _check_gemini_key()
    providers.append(
        {
            "name": "gemini",
            "available": gemini_key is not None,
            "version": None,
            "install_hint": None if gemini_key else "Set GEMINI_API_KEY environment variable",
        }
    )

    # 6. Voyage
    voyage_key = _check_voyage_key()
    providers.append(
        {
            "name": "voyage",
            "available": voyage_key is not None,
            "version": None,
            "install_hint": None if voyage_key else "Set VOYAGE_API_KEY environment variable",
        }
    )

    return providers


class EmbeddingChain:
    """Tries providers in order. Falls back on error."""

    def __init__(self, chain: list[str], models: dict[str, str] | None = None):
        self.chain_names = chain
        self.providers: list[EmbeddingProvider] = []
        self.models = models or {}
        self._last_error: str | None = None
        self._active_provider: str | None = None
        self._fallback_reason: str | None = None
        for name in chain:
            if name == "bm25":
                continue  # BM25 is always the implicit last resort
            try:
                provider = _create_provider(name, self.models.get(name))
                self.providers.append(provider)
            except (ImportError, ValueError):
                continue  # skip unavailable

    @property
    def name(self) -> str:
        """Display name for the chain."""
        return " → ".join(self.chain_names)

    @property
    def active_provider_name(self) -> str | None:
        """Name of the currently active (last successful) provider."""
        return self._active_provider

    @property
    def fallback_reason(self) -> str | None:
        """Reason why we fell back from the primary provider."""
        return self._fallback_reason

    def embed_query(self, text: str) -> tuple[list[float], str]:
        """Returns (vector, provider_name). Tries each provider in order."""
        self._fallback_reason = None
        primary_name = self.providers[0].name if self.providers else None
        for provider in self.providers:
            try:
                vector = provider.embed_query(text)
                self._active_provider = provider.name
                if provider.name != primary_name:
                    self._fallback_reason = self._last_error
                return vector, provider.name
            except Exception as e:
                self._last_error = f"{provider.name}: {e}"
                warnings.warn(f"{provider.name} failed: {e}, trying next...")
                continue
        # All failed → BM25 (return empty vector)
        self._active_provider = "bm25"
        if primary_name:
            self._fallback_reason = self._last_error
        return [], "bm25"

    def embed(self, texts: list[str]) -> tuple[list[list[float]], str]:
        """Batch embed. Returns (vectors, provider_name)."""
        self._fallback_reason = None
        primary_name = self.providers[0].name if self.providers else None
        for provider in self.providers:
            try:
                vectors = provider.embed(texts)
                self._active_provider = provider.name
                if provider.name != primary_name:
                    self._fallback_reason = self._last_error
                return vectors, provider.name
            except Exception as e:
                self._last_error = f"{provider.name}: {e}"
                warnings.warn(f"{provider.name} failed: {e}, trying next...")
                continue
        self._active_provider = "bm25"
        if primary_name:
            self._fallback_reason = self._last_error
        return [], "bm25"

    def provider_status(self) -> list[dict]:
        """Get status info for each provider in the chain."""
        detected = {p["name"]: p for p in detect_providers()}
        statuses = []
        for name in self.chain_names:
            if name == "bm25":
                statuses.append(
                    {
                        "name": "bm25",
                        "model": None,
                        "available": True,
                        "status": "always available",
                    }
                )
                continue
            info = detected.get(name, {})
            model = self.models.get(name)
            # Get default model from provider class
            if not model:
                defaults = {
                    "openai": OpenAIProvider.default_model,
                    "sentence-transformers": SentenceTransformersProvider.default_model,
                    "fastembed": FastEmbedProvider.default_model,
                    "ollama": OllamaProvider.default_model,
                    "gemini": GeminiProvider.default_model,
                }
                model = defaults.get(name)
            available = info.get("available", False)
            if name in ("openai", "gemini"):
                status = "API key found" if available else "no key found"
            elif name == "ollama":
                if info.get("server_running"):
                    status = "server running" if available else "model not pulled"
                else:
                    status = "server not running"
            else:
                status = "installed" if available else "not installed"
            statuses.append(
                {
                    "name": name,
                    "model": model,
                    "available": available,
                    "status": status,
                }
            )
        return statuses


def _resolve_embedding_models(config: dict) -> dict[str, str]:
    """Extract per-provider model overrides from config.

    Supports both:
      - embedding_model: "text-embedding-3-large"  (old format, applies to active provider)
      - embedding_model: {"openai": "text-embedding-3-large", ...}  (new format)
    """
    raw = config.get("embedding_model", "")
    if isinstance(raw, dict):
        return raw
    # Old format: single string → no per-provider mapping
    return {}


def _resolve_single_model(config: dict) -> str | None:
    """Get single model string for backward compat."""
    raw = config.get("embedding_model", "")
    if isinstance(raw, str) and raw:
        return raw
    return None


def build_embedding_chain(config: dict) -> EmbeddingChain:
    """Build an EmbeddingChain from config.

    Supports:
      - embedding_chain: ["openai", "sentence-transformers", "bm25"]
      - embedding_provider: "auto" (legacy, auto-detect)
      - embedding_provider: "sentence-transformers" (legacy, single provider)

    embedding_chain takes precedence over embedding_provider.
    """
    models = _resolve_embedding_models(config)
    single_model = _resolve_single_model(config)

    # New format: explicit chain
    chain = config.get("embedding_chain")
    if chain and isinstance(chain, list):
        # Ensure bm25 is always at the end
        if "bm25" not in chain:
            chain = chain + ["bm25"]
        return EmbeddingChain(chain, models)

    # Legacy format: embedding_provider
    provider_name = config.get("embedding_provider", "auto")

    if provider_name == "none":
        return EmbeddingChain(["bm25"], models)

    if provider_name != "auto":
        # Single explicit provider + bm25 fallback
        chain_list = [provider_name, "bm25"]
        # If single_model is set, map it to this provider
        if single_model and provider_name not in models:
            models[provider_name] = single_model
        return EmbeddingChain(chain_list, models)

    # Auto-detect: build chain from available providers
    detected = detect_providers()
    chain_list = []
    for p in detected:
        if p["available"] and p["name"] != "voyage":
            chain_list.append(p["name"])
    chain_list.append("bm25")
    if single_model:
        # Apply single model to first provider if no per-provider config
        if chain_list and chain_list[0] not in models:
            models[chain_list[0]] = single_model
    return EmbeddingChain(chain_list, models)


def auto_detect_provider(config: dict | None = None) -> EmbeddingProvider | BM25Provider:
    """Auto-detect the best available embedding provider.

    Order: ollama → sentence-transformers → fastembed → openai → bm25

    Args:
        config: Optional config dict with embedding_provider and embedding_model keys.

    Returns:
        An embedding provider instance.

    Note: For new code, prefer build_embedding_chain() which supports fallback chains.
    """
    config = config or {}
    provider_name = config.get("embedding_provider", "auto")
    model = config.get("embedding_model", "") or None
    # Handle dict-style embedding_model for backward compat
    if isinstance(model, dict):
        model = None

    if provider_name == "none":
        return BM25Provider()

    if provider_name != "auto":
        # Explicit provider requested
        return _create_provider(provider_name, model)

    # Auto-detect
    providers = detect_providers()
    for p in providers:
        if p["available"] and p["name"] != "voyage":  # voyage is not a provider we implement
            return _create_provider(p["name"], model)

    # Fallback
    return BM25Provider()


def _create_provider(name: str, model: str | None = None) -> EmbeddingProvider | BM25Provider:
    """Create a provider by name."""
    if name == "ollama":
        return OllamaProvider(model=model)
    elif name == "sentence-transformers":
        return SentenceTransformersProvider(model=model)
    elif name == "fastembed":
        return FastEmbedProvider(model=model)
    elif name == "openai":
        return OpenAIProvider(model=model)
    elif name == "gemini":
        return GeminiProvider(model=model)
    elif name == "bm25" or name == "none":
        return BM25Provider()
    else:
        raise ValueError(f"Unknown embedding provider: {name}")


def _repair_fastembed_cache_if_needed(model_name: str) -> None:
    """Check fastembed cache integrity and delete corrupted cache for re-download.

    Corrupted caches (e.g. broken symlinks from container/volume issues) cause
    cryptic ONNX runtime errors. This pre-check in warmup ensures a clean state.
    """
    import shutil
    from pathlib import Path

    model_short = model_name.split("/")[-1] if "/" in model_name else model_name
    cache_dir_name = f"models--qdrant--{model_short}-onnx-q"
    import tempfile

    cache_dir = Path(tempfile.gettempdir()) / "fastembed_cache" / cache_dir_name

    if not cache_dir.exists():
        return  # No cache yet — will be downloaded fresh

    # Check for ONNX files
    onnx_files = list(cache_dir.rglob("model_optimized.onnx")) + list(cache_dir.rglob("model.onnx"))

    corrupted = False
    if not onnx_files:
        corrupted = True
    else:
        for f in onnx_files:
            if f.is_symlink() and not f.resolve().exists():
                corrupted = True
                break
            if not f.is_file():
                corrupted = True
                break

    if corrupted:
        print(f"  [palaia] Corrupted fastembed cache detected — removing {cache_dir} for re-download")
        try:
            shutil.rmtree(cache_dir)
        except OSError as e:
            print(f"  [palaia] Warning: could not remove corrupted cache: {e}")


def warmup_providers(config: dict) -> list[dict]:
    """Pre-download and load embedding models for all providers in the chain.

    Returns a list of dicts with keys: name, status, message.
    status is one of: ready, skipped, action_needed, error.
    """
    import os

    models = _resolve_embedding_models(config)

    # Determine which providers to warm up
    chain = config.get("embedding_chain")
    if chain and isinstance(chain, list):
        provider_names = [p for p in chain if p != "bm25"]
    else:
        provider_name = config.get("embedding_provider", "auto")
        if provider_name in ("none", "auto"):
            # For auto, detect what's available
            if provider_name == "auto":
                detected = detect_providers()
                provider_names = [
                    p["name"] for p in detected if p["available"] and p["name"] not in ("voyage", "openai", "gemini")
                ]
            else:
                provider_names = []
        else:
            provider_names = [provider_name]

    if not provider_names:
        return []

    results = []
    for name in provider_names:
        model_override = models.get(name)
        try:
            if name == "sentence-transformers":
                model_name = model_override or SentenceTransformersProvider.default_model
                provider = SentenceTransformersProvider(model=model_name)
                provider._get_model()  # triggers download + load
                # Try to find cache path
                cache_dir = os.path.expanduser("~/.cache/huggingface/hub")
                results.append(
                    {
                        "name": name,
                        "status": "ready",
                        "message": f"Model loaded: {model_name} (cached at {cache_dir})",
                    }
                )
            elif name == "ollama":
                model_name = model_override or OllamaProvider.default_model
                server_running, _, available_models = _check_ollama_available()
                if not server_running:
                    results.append(
                        {
                            "name": name,
                            "status": "action_needed",
                            "message": "Ollama server not running. Start with: ollama serve",
                        }
                    )
                elif model_name not in available_models and model_name.split(":")[0] not in available_models:
                    results.append(
                        {
                            "name": name,
                            "status": "action_needed",
                            "message": f"Model '{model_name}' not pulled. Run: ollama pull {model_name}",
                        }
                    )
                else:
                    results.append(
                        {
                            "name": name,
                            "status": "ready",
                            "message": f"Model available: {model_name}",
                        }
                    )
            elif name == "fastembed":
                model_name = model_override or FastEmbedProvider.default_model
                # Pre-check: verify cache integrity before loading
                _repair_fastembed_cache_if_needed(model_name)
                provider = FastEmbedProvider(model=model_name)
                provider._get_model()  # triggers download
                results.append(
                    {
                        "name": name,
                        "status": "ready",
                        "message": f"Model loaded: {model_name}",
                    }
                )
            elif name == "openai":
                # Cloud provider — no model to download
                key = _check_openai_key()
                if key:
                    results.append(
                        {
                            "name": name,
                            "status": "skipped",
                            "message": "Cloud provider — no local model to pre-load. API key found.",
                        }
                    )
                else:
                    results.append(
                        {
                            "name": name,
                            "status": "action_needed",
                            "message": "No API key found. Set OPENAI_API_KEY environment variable.",
                        }
                    )
            elif name == "gemini":
                # Cloud provider — no model to download
                key = _check_gemini_key()
                if key:
                    model_name = model_override or GeminiProvider.default_model
                    results.append(
                        {
                            "name": name,
                            "status": "skipped",
                            "message": f"Cloud provider — no local model to pre-load. API key found. Model: {model_name}",
                        }
                    )
                else:
                    results.append(
                        {
                            "name": name,
                            "status": "action_needed",
                            "message": "No API key found. Set GEMINI_API_KEY environment variable.",
                        }
                    )
            else:
                results.append(
                    {
                        "name": name,
                        "status": "skipped",
                        "message": f"Unknown provider '{name}', skipping.",
                    }
                )
        except ImportError as e:
            results.append(
                {
                    "name": name,
                    "status": "error",
                    "message": f"Not installed: {e}",
                }
            )
        except Exception as e:
            results.append(
                {
                    "name": name,
                    "status": "error",
                    "message": str(e),
                }
            )

    return results


def get_provider_display_info(provider: EmbeddingProvider | BM25Provider) -> str:
    """Get a human-readable display string for a provider."""
    if isinstance(provider, BM25Provider):
        return "BM25 (keyword search)"
    name = getattr(provider, "name", "unknown")
    model = getattr(provider, "model_name", None) or getattr(provider, "model", None) or "default"
    return f"{name} ({model})"

"""Memory entry parsing and creation (ADR-006, ADR-012)."""

from __future__ import annotations

import hashlib
import os
import re
import uuid
from datetime import datetime, timezone

FRONTMATTER_RE = re.compile(r"^---\s*\n(.*?)\n---\s*\n?", re.DOTALL)

# Entry class types (ADR-012)
VALID_TYPES = {"memory", "process", "task"}
DEFAULT_TYPE = "memory"

# Task-specific structured fields (ADR-012)
VALID_STATUSES = {"open", "in-progress", "done", "wontfix"}
VALID_PRIORITIES = {"critical", "high", "medium", "low"}


def _parse_yaml_simple(text: str) -> dict:
    """Minimal YAML-like parser for frontmatter. No dependency needed.


    Handles: key: value, key: [a, b, c], quoted strings.
    """
    result = {}
    for line in text.strip().split("\n"):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if ":" not in line:
            continue
        # Only split on the FIRST colon to preserve colons in values (URLs, timestamps, etc.)
        key, _, value = line.partition(":")
        key = key.strip()
        value = value.strip()
        # List
        if value.startswith("[") and value.endswith("]"):
            items = value[1:-1].split(",")
            result[key] = [i.strip().strip("'\"") for i in items if i.strip()]
        # Number (int)
        elif value.isdigit():
            result[key] = int(value)
        # Float
        elif re.match(r"^\d+\.\d+$", value):
            result[key] = float(value)
        # Quoted string
        elif (value.startswith('"') and value.endswith('"')) or (value.startswith("'") and value.endswith("'")):
            result[key] = value[1:-1]
        else:
            result[key] = value
    return result


def _to_yaml_simple(data: dict) -> str:
    """Minimal dict → YAML-like frontmatter string."""
    lines = []
    for k, v in data.items():
        if isinstance(v, list):
            items = ", ".join(str(i) for i in v)
            lines.append(f"{k}: [{items}]")
        elif isinstance(v, float):
            lines.append(f"{k}: {v}")
        elif isinstance(v, int):
            lines.append(f"{k}: {v}")
        else:
            lines.append(f"{k}: {v}")
    return "\n".join(lines)


def extract_title_from_content(body: str, max_length: int = 80) -> str | None:
    """Extract a title from the first non-empty line of content.

    Strips markdown header prefixes (e.g. '# ', '## ').
    Truncates at ~max_length characters.
    Returns None if no usable title can be extracted.
    """
    for line in body.split("\n"):
        stripped = line.strip()
        if not stripped:
            continue
        # Strip markdown header prefixes (e.g. '# Title', '## Section')
        title = re.sub(r"^#{1,6}\s*", "", stripped)
        title = title.strip()
        if not title:
            continue
        if len(title) > max_length:
            title = title[:max_length].rsplit(" ", 1)[0] + "..."
        return title
    return None


def content_hash(text: str) -> str:
    """SHA-256 hash of content body."""
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def validate_entry_type(entry_type: str | None) -> str:
    """Validate and return entry type, defaulting to 'memory'."""
    if entry_type is None:
        return DEFAULT_TYPE
    entry_type = entry_type.strip().lower()
    if entry_type not in VALID_TYPES:
        raise ValueError(f"Invalid entry type: '{entry_type}'. Valid: {', '.join(sorted(VALID_TYPES))}")
    return entry_type


def validate_status(status: str | None) -> str | None:
    """Validate task status."""
    if status is None:
        return None
    status = status.strip().lower()
    if status not in VALID_STATUSES:
        raise ValueError(f"Invalid status: '{status}'. Valid: {', '.join(sorted(VALID_STATUSES))}")
    return status


def validate_priority(priority: str | None) -> str | None:
    """Validate task priority."""
    if priority is None:
        return None
    priority = priority.strip().lower()
    if priority not in VALID_PRIORITIES:
        raise ValueError(f"Invalid priority: '{priority}'. Valid: {', '.join(sorted(VALID_PRIORITIES))}")
    return priority


def _resolve_instance() -> str | None:
    """Resolve instance name from PALAIA_INSTANCE env var.

    Note: CLI layer resolves instance from config file (palaia instance set).
    This function is the low-level fallback for programmatic use.
    """
    return os.environ.get("PALAIA_INSTANCE") or None


def create_entry(
    body: str,
    scope: str = "team",
    agent: str | None = None,
    tags: list[str] | None = None,
    title: str | None = None,
    project: str | None = None,
    entry_type: str | None = None,
    status: str | None = None,
    priority: str | None = None,
    assignee: str | None = None,
    due_date: str | None = None,
    instance: str | None = None,
) -> str:
    """Create a full memory entry string with frontmatter."""
    now = datetime.now(timezone.utc).isoformat()
    entry_type = validate_entry_type(entry_type)

    meta = {
        "id": str(uuid.uuid4()),
        "type": entry_type,
        "scope": scope,
        "created": now,
        "accessed": now,
        "access_count": 1,
        "decay_score": 1.0,
        "content_hash": content_hash(body),
    }
    if agent:
        meta["agent"] = agent
    # Session identity (ADR-012)
    resolved_instance = instance or _resolve_instance()
    if resolved_instance:
        meta["instance"] = resolved_instance
    if tags:
        meta["tags"] = tags
    # Auto-extract title from content if not explicitly provided
    effective_title = title if title else extract_title_from_content(body)
    if effective_title:
        meta["title"] = effective_title
    if project:
        meta["project"] = project

    # Task-specific fields (only for type: task)
    if entry_type == "task":
        meta["status"] = validate_status(status) or "open"
        if priority:
            meta["priority"] = validate_priority(priority)
        if assignee:
            meta["assignee"] = assignee
        if due_date:
            meta["due_date"] = due_date

    fm = _to_yaml_simple(meta)
    return f"---\n{fm}\n---\n\n{body}\n"


def parse_entry(text: str) -> tuple[dict, str]:
    """Parse a memory entry into (metadata, body)."""
    m = FRONTMATTER_RE.match(text)
    if not m:
        return {}, text.strip()
    meta = _parse_yaml_simple(m.group(1))
    body = text[m.end() :].strip()
    return meta, body


def update_access(meta: dict) -> dict:
    """Update access metadata (timestamp, count, score)."""
    from palaia.decay import days_since, decay_score

    meta["accessed"] = datetime.now(timezone.utc).isoformat()
    meta["access_count"] = meta.get("access_count", 0) + 1
    days_since(meta.get("created", meta["accessed"]))
    meta["decay_score"] = decay_score(0, meta["access_count"])
    return meta


def serialize_entry(meta: dict, body: str) -> str:
    """Serialize metadata and body back to entry format."""
    fm = _to_yaml_simple(meta)
    return f"---\n{fm}\n---\n\n{body}\n"

"""File-based locking for concurrent access (ADR-007).

Cross-platform: uses fcntl on Unix, msvcrt on Windows.
Falls back to a simple mkdir-based lock if neither is available.
"""

from __future__ import annotations

import json
import os
import sys
import time
import warnings
from pathlib import Path

STALE_LOCK_SECONDS = 60

# Platform-specific locking primitives
_lock_impl = None  # "fcntl" | "msvcrt" | "mkdir"

if sys.platform != "win32":
    try:
        import fcntl as _fcntl

        _lock_impl = "fcntl"
    except ImportError:
        _lock_impl = "mkdir"
else:
    try:
        import msvcrt as _msvcrt

        _lock_impl = "msvcrt"
    except ImportError:
        _lock_impl = "mkdir"


class LockError(Exception):
    pass


def _flock_exclusive_nb(fd):
    """Acquire exclusive non-blocking flock (Unix)."""
    _fcntl.flock(fd, _fcntl.LOCK_EX | _fcntl.LOCK_NB)


def _flock_unlock(fd):
    """Release flock (Unix)."""
    _fcntl.flock(fd, _fcntl.LOCK_UN)


def _msvcrt_lock_nb(fd):
    """Acquire exclusive non-blocking lock (Windows)."""
    _msvcrt.locking(fd, _msvcrt.LK_NBLCK, 1)


def _msvcrt_unlock(fd):
    """Release lock (Windows)."""
    try:
        _msvcrt.locking(fd, _msvcrt.LK_UNLCK, 1)
    except OSError:
        pass


class PalaiaLock:
    """Advisory file lock with stale detection.

    Uses fcntl on Unix, msvcrt on Windows, mkdir-based fallback otherwise.
    """

    def __init__(self, palaia_root: Path, timeout: float = 5.0):
        self.lock_path = palaia_root / ".lock"
        self.timeout = timeout
        self._fd = None
        self._mkdir_lock = None  # Path for mkdir fallback

    def _check_stale(self) -> bool:
        """Check if existing lock is stale (>60s old). If stale, remove it and warn."""
        if not self.lock_path.exists():
            return False
        try:
            with open(self.lock_path, "r") as f:
                data = json.load(f)
            lock_ts = data.get("ts", 0)
            lock_pid = data.get("pid", 0)
            age = time.time() - lock_ts
            if age > STALE_LOCK_SECONDS:
                warnings.warn(
                    f"Stale lock detected (age: {age:.0f}s, pid: {lock_pid}). Overriding stale lock.",
                    stacklevel=3,
                )
                try:
                    self.lock_path.unlink(missing_ok=True)
                except OSError:
                    pass
                return True
        except (json.JSONDecodeError, OSError, ValueError):
            # Corrupt lock file — treat as stale
            try:
                self.lock_path.unlink(missing_ok=True)
            except OSError:
                pass
            return True
        return False

    def _write_lock_info(self, fd):
        """Write PID and timestamp to the lock file descriptor."""
        fd.write(json.dumps({"pid": os.getpid(), "ts": time.time()}))
        fd.flush()

    def _acquire_fcntl(self) -> None:
        """Acquire lock using fcntl (Unix)."""
        deadline = time.monotonic() + self.timeout
        self.lock_path.parent.mkdir(parents=True, exist_ok=True)
        self._check_stale()

        self._fd = open(self.lock_path, "w")
        while True:
            try:
                _flock_exclusive_nb(self._fd)
                self._write_lock_info(self._fd)
                return
            except (IOError, OSError):
                if time.monotonic() >= deadline:
                    if self._check_stale():
                        try:
                            self._fd.close()
                            self._fd = open(self.lock_path, "w")
                            _flock_exclusive_nb(self._fd)
                            self._write_lock_info(self._fd)
                            return
                        except (IOError, OSError):
                            pass
                    self._fd.close()
                    self._fd = None
                    raise LockError(f"Could not acquire lock within {self.timeout}s")
                time.sleep(0.05)

    def _release_fcntl(self) -> None:
        """Release fcntl lock."""
        if self._fd:
            try:
                _flock_unlock(self._fd)
                self._fd.close()
            except (IOError, OSError):
                pass
            self._fd = None
            try:
                self.lock_path.unlink(missing_ok=True)
            except OSError:
                pass

    def _acquire_msvcrt(self) -> None:
        """Acquire lock using msvcrt (Windows)."""
        deadline = time.monotonic() + self.timeout
        self.lock_path.parent.mkdir(parents=True, exist_ok=True)
        self._check_stale()

        self._fd = open(self.lock_path, "w")
        while True:
            try:
                _msvcrt_lock_nb(self._fd.fileno())
                self._write_lock_info(self._fd)
                return
            except (IOError, OSError):
                if time.monotonic() >= deadline:
                    if self._check_stale():
                        try:
                            self._fd.close()
                            self._fd = open(self.lock_path, "w")
                            _msvcrt_lock_nb(self._fd.fileno())
                            self._write_lock_info(self._fd)
                            return
                        except (IOError, OSError):
                            pass
                    self._fd.close()
                    self._fd = None
                    raise LockError(f"Could not acquire lock within {self.timeout}s")
                time.sleep(0.05)

    def _release_msvcrt(self) -> None:
        """Release msvcrt lock."""
        if self._fd:
            try:
                _msvcrt_unlock(self._fd.fileno())
                self._fd.close()
            except (IOError, OSError):
                pass
            self._fd = None
            try:
                self.lock_path.unlink(missing_ok=True)
            except OSError:
                pass

    def _acquire_mkdir(self) -> None:
        """Acquire lock using mkdir atomicity (fallback)."""
        deadline = time.monotonic() + self.timeout
        self._mkdir_lock = self.lock_path.with_suffix(".lk")
        self._check_stale()

        while True:
            try:
                self._mkdir_lock.mkdir(parents=True, exist_ok=False)
                # Write lock info to the regular lock file for stale detection
                self.lock_path.parent.mkdir(parents=True, exist_ok=True)
                with open(self.lock_path, "w") as f:
                    f.write(json.dumps({"pid": os.getpid(), "ts": time.time()}))
                return
            except FileExistsError:
                if time.monotonic() >= deadline:
                    if self._check_stale():
                        try:
                            self._mkdir_lock.rmdir()
                        except OSError:
                            pass
                        try:
                            self._mkdir_lock.mkdir(exist_ok=False)
                            with open(self.lock_path, "w") as f:
                                f.write(json.dumps({"pid": os.getpid(), "ts": time.time()}))
                            return
                        except (FileExistsError, OSError):
                            pass
                    raise LockError(f"Could not acquire lock within {self.timeout}s")
                time.sleep(0.05)

    def _release_mkdir(self) -> None:
        """Release mkdir lock."""
        if self._mkdir_lock:
            try:
                self._mkdir_lock.rmdir()
            except OSError:
                pass
            self._mkdir_lock = None
        try:
            self.lock_path.unlink(missing_ok=True)
        except OSError:
            pass

    def acquire(self) -> None:
        if _lock_impl == "fcntl":
            self._acquire_fcntl()
        elif _lock_impl == "msvcrt":
            self._acquire_msvcrt()
        else:
            self._acquire_mkdir()

    def release(self) -> None:
        if _lock_impl == "fcntl":
            self._release_fcntl()
        elif _lock_impl == "msvcrt":
            self._release_msvcrt()
        else:
            self._release_mkdir()

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, *args):
        self.release()

"""Migration from external memory formats into Palaia (palaia migrate)."""

from __future__ import annotations

import json
import re
import time
from abc import ABC, abstractmethod
from pathlib import Path

from palaia.entry import content_hash
from palaia.store import Store

# System files that agents read at runtime — must never be deleted after migration.
SYSTEM_FILE_PATTERNS = {
    "CONTEXT.md",
    "SOUL.md",
    "MEMORY.md",
    "AGENTS.md",
    "TOOLS.md",
    "USER.md",
    "IDENTITY.md",
}


def is_system_file(path_str: str) -> bool:
    """Check if a path refers to an agent system file."""
    basename = Path(path_str).name
    return basename in SYSTEM_FILE_PATTERNS


class MigrationEntry:
    """A single entry extracted by an adapter."""

    def __init__(
        self,
        body: str,
        scope: str = "team",
        tier: str = "hot",
        title: str | None = None,
        tags: list[str] | None = None,
        agent: str | None = None,
        source_file: str | None = None,
    ):
        self.body = body
        self.scope = scope
        self.tier = tier
        self.title = title
        self.tags = tags
        self.agent = agent
        self.source_file = source_file

    def __repr__(self) -> str:
        return f"MigrationEntry(title={self.title!r}, scope={self.scope}, tier={self.tier})"


class BaseAdapter(ABC):
    """Base class for migration adapters."""

    name: str = "base"

    @classmethod
    @abstractmethod
    def detect(cls, source: Path) -> bool:
        """Return True if source matches this format."""
        ...

    @classmethod
    @abstractmethod
    def extract(cls, source: Path) -> list[MigrationEntry]:
        """Extract entries from source."""
        ...


class SmartMemoryAdapter(BaseAdapter):
    """Reads OpenClaw smart-memory 5-layer architecture."""

    name = "smart-memory"

    @classmethod
    def detect(cls, source: Path) -> bool:
        if not source.is_dir():
            return False
        has_memory_md = (source / "MEMORY.md").is_file()
        has_active = (source / "memory" / "active-context.md").is_file()
        return has_memory_md and has_active

    @classmethod
    def extract(cls, source: Path) -> list[MigrationEntry]:
        entries: list[MigrationEntry] = []

        # MEMORY.md → 1 entry, scope=team, tier=HOT
        memory_md = source / "MEMORY.md"
        if memory_md.is_file():
            body = memory_md.read_text(encoding="utf-8").strip()
            if body:
                entries.append(
                    MigrationEntry(
                        body=body,
                        scope="team",
                        tier="hot",
                        title="MEMORY.md",
                        source_file="MEMORY.md",
                    )
                )

        # memory/active-context.md → per ## [OPEN] block
        active = source / "memory" / "active-context.md"
        if active.is_file():
            entries.extend(cls._parse_active_context(active))

        # memory/projects/*/CONTEXT.md → 1 entry per file
        projects_dir = source / "memory" / "projects"
        if projects_dir.is_dir():
            for proj_dir in sorted(projects_dir.iterdir()):
                if proj_dir.is_dir():
                    ctx = proj_dir / "CONTEXT.md"
                    if ctx.is_file():
                        body = ctx.read_text(encoding="utf-8").strip()
                        if body:
                            proj_name = proj_dir.name
                            entries.append(
                                MigrationEntry(
                                    body=body,
                                    scope=f"shared:{proj_name}",
                                    tier="hot",
                                    title=f"Project: {proj_name}",
                                    source_file=str(ctx.relative_to(source)),
                                )
                            )

        # memory/agents/*.md → 1 entry per file, scope=team, tier=WARM
        agents_dir = source / "memory" / "agents"
        if agents_dir.is_dir():
            for md in sorted(agents_dir.glob("*.md")):
                body = md.read_text(encoding="utf-8").strip()
                if body:
                    entries.append(
                        MigrationEntry(
                            body=body,
                            scope="team",
                            tier="warm",
                            title=f"Agent: {md.stem}",
                            source_file=str(md.relative_to(source)),
                        )
                    )

        # memory/YYYY-MM-DD.md → 1 entry per file, scope=team, tier=COLD
        memory_dir = source / "memory"
        if memory_dir.is_dir():
            date_re = re.compile(r"^\d{4}-\d{2}-\d{2}\.md$")
            for md in sorted(memory_dir.glob("*.md")):
                if date_re.match(md.name):
                    body = md.read_text(encoding="utf-8").strip()
                    if body:
                        entries.append(
                            MigrationEntry(
                                body=body,
                                scope="team",
                                tier="cold",
                                title=f"Daily: {md.stem}",
                                source_file=str(md.relative_to(source)),
                            )
                        )

        return entries

    @classmethod
    def _parse_active_context(cls, path: Path) -> list[MigrationEntry]:
        """Split active-context.md by ## [OPEN] blocks."""
        text = path.read_text(encoding="utf-8")
        entries: list[MigrationEntry] = []
        blocks = re.split(r"(?=^## \[OPEN\])", text, flags=re.MULTILINE)
        for block in blocks:
            block = block.strip()
            if not block.startswith("## [OPEN]"):
                continue
            # Extract title from first line
            first_line = block.split("\n", 1)[0]
            title = first_line.replace("## [OPEN]", "").strip()
            entries.append(
                MigrationEntry(
                    body=block,
                    scope="team",
                    tier="hot",
                    title=title or "Active Context",
                    source_file=str(path.name),
                )
            )
        return entries


class FlatFileAdapter(BaseAdapter):
    """Single .md file or file with --- separators."""

    name = "flat-file"

    @classmethod
    def detect(cls, source: Path) -> bool:
        return source.is_file() and source.suffix == ".md"

    @classmethod
    def extract(cls, source: Path) -> list[MigrationEntry]:
        text = source.read_text(encoding="utf-8").strip()
        if not text:
            return []

        # Split by --- separator (only if between content, not frontmatter)
        # Skip frontmatter-style --- at very start
        sections = re.split(r"\n---\n", text)
        entries = []
        for i, section in enumerate(sections):
            section = section.strip()
            if not section:
                continue
            title = None
            # Try to extract first heading as title
            m = re.match(r"^#+ (.+)", section)
            if m:
                title = m.group(1).strip()
            if not title:
                title = f"{source.stem} (part {i + 1})" if len(sections) > 1 else source.stem
            entries.append(
                MigrationEntry(
                    body=section,
                    scope="team",
                    tier="hot",
                    title=title,
                    source_file=source.name,
                )
            )
        return entries


class JsonMemoryAdapter(BaseAdapter):
    """JSON array of memory objects."""

    name = "json-memory"

    @classmethod
    def detect(cls, source: Path) -> bool:
        if source.is_file() and source.suffix == ".json":
            return cls._is_memory_json(source)
        if source.is_dir():
            for f in source.glob("*.json"):
                if cls._is_memory_json(f):
                    return True
        return False

    @classmethod
    def _is_memory_json(cls, path: Path) -> bool:
        try:
            with open(path) as f:
                data = json.load(f)
            return isinstance(data, list) and len(data) > 0 and isinstance(data[0], dict) and "content" in data[0]
        except (json.JSONDecodeError, OSError, IndexError):
            return False

    @classmethod
    def extract(cls, source: Path) -> list[MigrationEntry]:
        files = [source] if source.is_file() else sorted(source.glob("*.json"))
        entries = []
        for f in files:
            try:
                with open(f) as fh:
                    data = json.load(fh)
                if not isinstance(data, list):
                    continue
                for item in data:
                    if not isinstance(item, dict) or "content" not in item:
                        continue
                    meta = item.get("metadata", {})
                    entries.append(
                        MigrationEntry(
                            body=item["content"],
                            scope=meta.get("scope", "team"),
                            tier="hot",
                            title=item.get("title") or meta.get("title"),
                            tags=meta.get("tags"),
                            agent=meta.get("agent"),
                            source_file=f.name,
                        )
                    )
            except (json.JSONDecodeError, OSError):
                continue
        return entries


class GenericMarkdownAdapter(BaseAdapter):
    """Fallback: each .md file in directory → 1 entry."""

    name = "generic-md"

    DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}")

    @classmethod
    def detect(cls, source: Path) -> bool:
        if source.is_dir():
            return any(source.glob("*.md"))
        return source.is_file() and source.suffix == ".md"

    @classmethod
    def extract(cls, source: Path) -> list[MigrationEntry]:
        if source.is_file():
            return cls._extract_file(source)
        entries = []
        for md in sorted(source.rglob("*.md")):
            entries.extend(cls._extract_file(md, base=source))
        return entries

    @classmethod
    def _extract_file(cls, path: Path, base: Path | None = None) -> list[MigrationEntry]:
        body = path.read_text(encoding="utf-8").strip()
        if not body:
            return []
        name_lower = path.stem.lower()
        tier = cls._guess_tier(path, name_lower)
        scope = cls._guess_scope(name_lower)
        title_match = re.match(r"^#+ (.+)", body)
        title = title_match.group(1).strip() if title_match else path.stem
        rel = str(path.relative_to(base)) if base else path.name
        return [MigrationEntry(body=body, scope=scope, tier=tier, title=title, source_file=rel)]

    @classmethod
    def _guess_tier(cls, path: Path, name_lower: str) -> str:
        if cls.DATE_RE.match(name_lower):
            return "cold"
        for kw in ("active", "current", "hot"):
            if kw in name_lower:
                return "hot"
        for kw in ("archive", "old", "cold"):
            if kw in name_lower:
                return "cold"
        # Fall back to mtime
        try:
            mtime = path.stat().st_mtime
            days = (time.time() - mtime) / 86400
            if days < 7:
                return "hot"
            if days < 30:
                return "warm"
            return "cold"
        except OSError:
            return "warm"

    @classmethod
    def _guess_scope(cls, name_lower: str) -> str:
        if "private" in name_lower:
            return "private"
        if "public" in name_lower:
            return "public"
        return "team"


# Adapter registry — order matters (most specific first)
ADAPTERS: list[type[BaseAdapter]] = [
    SmartMemoryAdapter,
    JsonMemoryAdapter,
    FlatFileAdapter,
    GenericMarkdownAdapter,
]


def detect_format(source_path: Path) -> str:
    """Auto-detect source format. Returns adapter name."""
    for adapter_cls in ADAPTERS:
        if adapter_cls.detect(source_path):
            return adapter_cls.name
    return "generic-md"


def get_adapter(name: str) -> type[BaseAdapter]:
    """Get adapter class by name."""
    for adapter_cls in ADAPTERS:
        if adapter_cls.name == name:
            return adapter_cls
    raise ValueError(f"Unknown format: {name}. Available: {[a.name for a in ADAPTERS]}")


def migrate(
    source: str | Path,
    store: Store,
    format_name: str | None = None,
    scope_override: str | None = None,
    dry_run: bool = False,
) -> dict:
    """Run migration.

    Args:
        source: Path to source directory or file.
        store: Target Palaia store.
        format_name: Force a specific format (None = auto-detect).
        scope_override: Override scope for all entries.
        dry_run: If True, report what would be imported.

    Returns:
        dict with migration stats.
    """
    source = Path(source)
    if not source.exists():
        raise FileNotFoundError(f"Source not found: {source}")

    # Detect or use forced format
    detected = format_name or detect_format(source)
    adapter = get_adapter(detected)

    # Extract
    entries = adapter.extract(source)

    # Apply scope override
    if scope_override:
        for e in entries:
            e.scope = scope_override

    # Count stats
    tier_counts = {"hot": 0, "warm": 0, "cold": 0}
    scope_counts: dict[str, int] = {}
    files_seen: set[str] = set()
    system_files_detected: list[str] = []
    for e in entries:
        tier_counts[e.tier] = tier_counts.get(e.tier, 0) + 1
        scope_counts[e.scope] = scope_counts.get(e.scope, 0) + 1
        if e.source_file:
            files_seen.add(e.source_file)
            if is_system_file(e.source_file) and e.source_file not in system_files_detected:
                system_files_detected.append(e.source_file)

    result = {
        "format": detected,
        "total_entries": len(entries),
        "files_scanned": len(files_seen),
        "tiers": tier_counts,
        "scopes": scope_counts,
        "imported": 0,
        "skipped_dedup": 0,
        "dry_run": dry_run,
        "system_files_detected": system_files_detected,
    }

    if dry_run:
        result["entries"] = [
            {"title": e.title, "scope": e.scope, "tier": e.tier, "source": e.source_file} for e in entries
        ]
        return result

    # Import entries
    imported = 0
    skipped = 0
    for e in entries:
        h = content_hash(e.body)
        existing = store._find_by_hash(h)
        if existing:
            skipped += 1
            continue
        store.write(
            body=e.body,
            scope=e.scope,
            agent=e.agent,
            tags=e.tags,
            title=e.title,
        )
        imported += 1

    result["imported"] = imported
    result["skipped_dedup"] = skipped
    return result


def format_result(result: dict) -> str:
    """Format migration result for CLI output."""
    lines = [f"Detected format: {result['format']}"]
    lines.append(f"Found {result['total_entries']} entries across {result['files_scanned']} files")

    tiers = result["tiers"]
    lines.append(f"  → {tiers.get('hot', 0)} HOT, {tiers.get('warm', 0)} WARM, {tiers.get('cold', 0)} COLD")

    scopes = result["scopes"]
    scope_parts = [f"{k} ({v})" for k, v in sorted(scopes.items(), key=lambda x: -x[1])]
    lines.append(f"  → scope: {', '.join(scope_parts)}")

    if result["dry_run"]:
        lines.append("")
        lines.append("Dry run — nothing written.")
        if result.get("entries"):
            for e in result["entries"]:
                lines.append(f"  {e['tier'].upper():5} [{e['scope']}] {e['title']} ← {e['source']}")
    else:
        lines.append("")
        lines.append(f"Done. {result['imported']} entries imported, {result['skipped_dedup']} duplicates skipped.")

    # Warn about system files that were processed
    system_files = result.get("system_files_detected", [])
    if system_files:
        lines.append("")
        for sf in system_files:
            lines.append(f"Warning: System file detected: {sf}")
            lines.append("    This file is used at runtime by agents. It was copied to Palaia but NOT deleted.")
            lines.append("    Do not remove it manually.")
        lines.append("")
        lines.append("See: https://github.com/iret77/palaia/blob/main/docs/migration-guide.md")

    return "\n".join(lines)

"""Adaptive Nudging with Graduation System (Issue #68).

Palaia nudges agents toward better practices (e.g. using --type, --tags)
via CLI output hints. But nudges should educate agents toward independence,
not prop them up indefinitely. Once an agent demonstrates consistent good
behavior (3 consecutive successes), the nudge "graduates" and stops.

Regression detection: if a graduated agent falls back to bad habits,
the nudge is re-activated.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

# Default patterns and their nudge messages
NUDGE_PATTERNS: dict[str, dict[str, str]] = {
    "write_without_type": {
        "message": (
            "Tip: Use --type (memory|process|task) for better recall. "
            "Save this hint to your memory so you won't need it next time."
        ),
    },
    "write_without_tags": {
        "message": (
            "Tip: Tags improve discoverability. Use --tags for categorization. "
            "Save this hint to your memory so you won't need it next time."
        ),
    },
    "write_without_project": {
        "message": (
            "Tip: In multi-project setups, --project helps with attribution. "
            "Save this hint to your memory so you won't need it next time."
        ),
    },
    "query_without_type_filter": {
        "message": (
            "Tip: Use --type (memory|process|task) to focus search results. "
            "Save this hint to your memory so you won't need it next time."
        ),
    },
    "satisfaction_check": {
        "message": (
            "Your user has been using Palaia for a while now. "
            "Ask them casually if they're happy with the memory system. "
            "If there are issues, suggest `palaia doctor`."
        ),
    },
    "transparency_preference": {
        "message": (
            "Your user has been seeing memory Footnotes and capture confirmations "
            "for several days now. Ask them once: 'Would you like to keep seeing "
            "memory source references and capture confirmations, or should I hide them? "
            "You can change this anytime.' "
            "Based on their answer: `palaia config set showMemorySources true/false` "
            "and `palaia config set showCaptureConfirm true/false`"
        ),
    },
}

# Graduation threshold: consecutive successes required
GRADUATION_THRESHOLD = 3

# Frequency limit: max 1 nudge per pattern per hour (seconds)
NUDGE_COOLDOWN_SECONDS = 3600


class NudgeTracker:
    """Tracks nudge state per agent with graduation and regression support.

    Storage: .palaia/nudge-state.json
    Schema per pattern_id:
        {
            "nudge_count": int,
            "success_count": int,
            "consecutive_success": int,
            "graduated": bool,
            "last_nudge": iso_timestamp | null,
            "last_regression": iso_timestamp | null
        }
    """

    def __init__(self, palaia_root: Path):
        self.root = palaia_root
        self.state_file = palaia_root / "nudge-state.json"
        self._state: dict[str, dict[str, Any]] = self._load()

    def _load(self) -> dict[str, dict[str, Any]]:
        """Load nudge state from disk."""
        if self.state_file.exists():
            try:
                return json.loads(self.state_file.read_text())
            except (json.JSONDecodeError, OSError):
                return {}
        return {}

    def _save(self) -> None:
        """Persist nudge state to disk."""
        try:
            self.state_file.write_text(json.dumps(self._state, indent=2))
        except OSError:
            pass

    def _agent_key(self, agent: str) -> str:
        """Get the key for agent-level state."""
        return agent or "default"

    def _get_pattern_state(self, pattern_id: str, agent: str) -> dict[str, Any]:
        """Get or create state for a specific pattern+agent combo."""
        agent_key = self._agent_key(agent)
        agent_state = self._state.setdefault(agent_key, {})
        if pattern_id not in agent_state:
            agent_state[pattern_id] = {
                "nudge_count": 0,
                "success_count": 0,
                "consecutive_success": 0,
                "graduated": False,
                "last_nudge": None,
                "last_regression": None,
            }
        return agent_state[pattern_id]

    def should_nudge(self, pattern_id: str, agent: str) -> bool:
        """Check if a nudge should be shown for this pattern.

        Returns True if:
        - Pattern is not graduated
        - Cooldown period has elapsed (max 1 nudge per pattern per hour)
        """
        state = self._get_pattern_state(pattern_id, agent)

        if state["graduated"]:
            return False

        # Frequency limit
        last_nudge = state.get("last_nudge")
        if last_nudge:
            try:
                from datetime import datetime, timezone

                last_time = datetime.fromisoformat(last_nudge)
                if last_time.tzinfo is None:
                    last_time = last_time.replace(tzinfo=timezone.utc)
                now = datetime.now(timezone.utc)
                elapsed = (now - last_time).total_seconds()
                if elapsed < NUDGE_COOLDOWN_SECONDS:
                    return False
            except (ValueError, TypeError):
                pass  # Invalid timestamp, allow nudge

        return True

    def record_nudge(self, pattern_id: str, agent: str) -> None:
        """Record that a nudge was shown."""
        from datetime import datetime, timezone

        state = self._get_pattern_state(pattern_id, agent)
        state["nudge_count"] = state.get("nudge_count", 0) + 1
        state["last_nudge"] = datetime.now(timezone.utc).isoformat()
        self._save()

    def record_success(self, pattern_id: str, agent: str) -> None:
        """Record that the agent used the recommended feature.

        After GRADUATION_THRESHOLD consecutive successes, the pattern graduates.
        """
        state = self._get_pattern_state(pattern_id, agent)
        state["success_count"] = state.get("success_count", 0) + 1
        state["consecutive_success"] = state.get("consecutive_success", 0) + 1

        if state["consecutive_success"] >= GRADUATION_THRESHOLD:
            state["graduated"] = True

        self._save()

    def record_failure(self, pattern_id: str, agent: str) -> None:
        """Record that the agent did NOT use the recommended feature.

        Resets consecutive success counter. If graduated, triggers regression.
        """
        from datetime import datetime, timezone

        state = self._get_pattern_state(pattern_id, agent)
        state["consecutive_success"] = 0

        if state["graduated"]:
            state["graduated"] = False
            state["last_regression"] = datetime.now(timezone.utc).isoformat()

        self._save()

    def get_state(self, pattern_id: str, agent: str) -> dict[str, Any]:
        """Get the current state for a pattern+agent (read-only copy)."""
        return dict(self._get_pattern_state(pattern_id, agent))

    def get_all_states(self, agent: str) -> dict[str, dict[str, Any]]:
        """Get all pattern states for an agent."""
        agent_key = self._agent_key(agent)
        return dict(self._state.get(agent_key, {}))

    def get_nudge_message(self, pattern_id: str) -> str | None:
        """Get the nudge message for a pattern."""
        pattern = NUDGE_PATTERNS.get(pattern_id)
        if pattern:
            return pattern["message"]
        return None

"""First-class project management for Palaia (ADR-008).

Projects are optional containers for grouping related entries.
They are stored in .palaia/projects.json and add a 'project' field
to entry frontmatter.
"""

from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path

from palaia.scope import validate_scope


class Project:
    """A project container."""

    def __init__(
        self,
        name: str,
        description: str = "",
        default_scope: str = "team",
        created_at: str | None = None,
        members: list[str] | None = None,
        owner: str | None = None,
    ):
        self.name = name
        self.description = description
        self.default_scope = default_scope
        self.created_at = created_at or datetime.now(timezone.utc).isoformat()
        self.members = members or []
        self.owner = owner

    def to_dict(self) -> dict:
        return {
            "name": self.name,
            "description": self.description,
            "default_scope": self.default_scope,
            "created_at": self.created_at,
            "members": self.members,
            "owner": self.owner,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Project":
        return cls(
            name=data["name"],
            description=data.get("description", ""),
            default_scope=data.get("default_scope", "team"),
            created_at=data.get("created_at"),
            members=data.get("members", []),
            owner=data.get("owner"),
        )


class ProjectManager:
    """Manages projects stored in .palaia/projects.json."""

    def __init__(self, palaia_root: Path):
        self.root = palaia_root
        self.projects_file = palaia_root / "projects.json"

    def _load(self) -> dict[str, dict]:
        """Load projects from disk."""
        if not self.projects_file.exists():
            return {}
        try:
            with open(self.projects_file, "r") as f:
                data = json.load(f)
            if not isinstance(data, dict):
                return {}
            return data
        except (json.JSONDecodeError, OSError):
            return {}

    def _save(self, data: dict[str, dict]) -> None:
        """Save projects to disk."""
        with open(self.projects_file, "w") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)

    def create(
        self,
        name: str,
        description: str = "",
        default_scope: str = "team",
        owner: str | None = None,
    ) -> Project:
        """Create a new project."""
        if not name or not name.strip():
            raise ValueError("Project name cannot be empty.")

        # Validate scope
        if not validate_scope(default_scope):
            raise ValueError(f"Invalid scope: '{default_scope}'.")

        data = self._load()
        if name in data:
            raise ValueError(f"Project '{name}' already exists.")

        project = Project(name=name, description=description, default_scope=default_scope, owner=owner)
        data[name] = project.to_dict()
        self._save(data)
        return project

    def list(self) -> list[Project]:
        """List all projects."""
        data = self._load()
        return [Project.from_dict(v) for v in data.values()]

    def get(self, name: str) -> Project | None:
        """Get a project by name."""
        data = self._load()
        if name not in data:
            return None
        return Project.from_dict(data[name])

    def ensure(self, name: str, default_scope: str = "team") -> Project:
        """Get a project by name, creating it if it doesn't exist.

        This is the recommended way to reference projects from CLI commands
        that accept --project. It avoids the user having to manually create
        projects before using them.
        """
        project = self.get(name)
        if project is not None:
            return project
        return self.create(name=name, default_scope=default_scope)

    def delete(self, name: str, store=None) -> bool:
        """Delete a project. Entries keep their content but lose the project tag."""
        data = self._load()
        if name not in data:
            return False

        del data[name]
        self._save(data)

        # Remove project tag from entries
        if store is not None:
            self._strip_project_from_entries(name, store)

        return True

    def set_scope(self, name: str, scope: str) -> Project:
        """Change a project's default scope."""
        if not validate_scope(scope):
            raise ValueError(f"Invalid scope: '{scope}'.")

        data = self._load()
        if name not in data:
            raise ValueError(f"Project '{name}' not found.")

        data[name]["default_scope"] = scope
        self._save(data)
        return Project.from_dict(data[name])

    def set_owner(self, name: str, owner: str) -> Project:
        """Set or change a project's owner."""
        data = self._load()
        if name not in data:
            raise ValueError(f"Project '{name}' not found.")

        data[name]["owner"] = owner
        self._save(data)
        return Project.from_dict(data[name])

    def clear_owner(self, name: str) -> Project:
        """Remove a project's owner."""
        data = self._load()
        if name not in data:
            raise ValueError(f"Project '{name}' not found.")

        data[name]["owner"] = None
        self._save(data)
        return Project.from_dict(data[name])

    def get_contributors(self, name: str, store) -> list[str]:
        """Get distinct agent names from all entries of a project."""
        entries = self.get_project_entries(name, store)
        agents = set()
        for meta, _body, _tier in entries:
            agent = meta.get("agent")
            if agent:
                agents.add(agent)
        return sorted(agents)

    def _strip_project_from_entries(self, project_name: str, store) -> int:
        """Remove project tag from all entries belonging to a project."""
        from palaia.entry import parse_entry, serialize_entry

        count = 0
        for tier in ("hot", "warm", "cold"):
            tier_dir = store.root / tier
            if not tier_dir.exists():
                continue
            for p in tier_dir.glob("*.md"):
                try:
                    text = p.read_text(encoding="utf-8")
                    meta, body = parse_entry(text)
                    if meta.get("project") == project_name:
                        del meta["project"]
                        new_text = serialize_entry(meta, body)
                        store.write_raw(str(p.relative_to(store.root)), new_text)
                        count += 1
                except (OSError, UnicodeDecodeError):
                    continue
        return count

    def get_project_entries(self, name: str, store) -> list[tuple[dict, str, str]]:
        """Get all entries belonging to a project."""
        from palaia.entry import parse_entry

        results = []
        for tier in ("hot", "warm", "cold"):
            tier_dir = store.root / tier
            if not tier_dir.exists():
                continue
            for p in sorted(tier_dir.glob("*.md")):
                try:
                    text = p.read_text(encoding="utf-8")
                    meta, body = parse_entry(text)
                    if meta.get("project") == name:
                        results.append((meta, body, tier))
                except (OSError, UnicodeDecodeError):
                    continue
        return results

"""Scope-Tag parsing and enforcement (ADR-002)."""

from __future__ import annotations

VALID_SCOPES = {"private", "team", "public"}
SHARED_PREFIX = "shared:"


def validate_scope(scope: str) -> bool:
    """Check if a scope string is valid."""
    if scope in VALID_SCOPES:
        return True
    if scope.startswith(SHARED_PREFIX) and len(scope) > len(SHARED_PREFIX):
        return True
    return False


def normalize_scope(scope: str | None, default: str = "team") -> str:
    """Normalize and validate a scope, returning default if None."""
    if scope is None:
        return default
    scope = scope.strip().lower()
    if not validate_scope(scope):
        raise ValueError(f"Invalid scope: '{scope}'. Valid: private, team, shared:<name>, public")
    return scope


def can_access(
    entry_scope: str,
    agent_name: str | None,
    entry_agent: str | None,
    projects: list[str] | None = None,
    agent_names: set[str] | None = None,
) -> bool:
    """Check if an agent can access an entry based on scope rules.

    Args:
        agent_names: Set of all agent names that should be treated as equivalent
                     (resolved via aliases). If provided, used for private scope
                     matching instead of exact agent_name comparison.
    """
    if entry_scope == "team":
        return True
    if entry_scope == "public":
        return True
    if entry_scope == "private":
        if agent_name is None:
            return False
        if agent_names:
            return entry_agent in agent_names
        return agent_name == entry_agent
    if entry_scope.startswith(SHARED_PREFIX):
        project = entry_scope[len(SHARED_PREFIX) :]
        return projects is not None and project in projects
    return False


def is_exportable(scope: str) -> bool:
    """Only public memories can be exported."""
    return scope == "public"

"""Hybrid search: BM25 + semantic embeddings (ADR-001)."""

from __future__ import annotations

import math
import re
from collections import Counter

from palaia.embeddings import (
    BM25Provider,
    _create_provider,
    _resolve_embedding_models,
    auto_detect_provider,
    cosine_similarity,
    detect_providers,
    get_provider_display_info,
)


def tokenize(text: str) -> list[str]:
    """Simple whitespace + punctuation tokenizer."""
    text = text.lower()
    tokens = re.findall(r"\b\w+\b", text)
    return tokens


class BM25:
    """BM25 ranking algorithm — pure Python, zero dependencies."""

    def __init__(self, k1: float = 1.5, b: float = 0.75):
        self.k1 = k1
        self.b = b
        self.corpus: list[tuple[str, list[str]]] = []  # (doc_id, tokens)
        self.doc_freqs: Counter = Counter()
        self.doc_lens: list[int] = []
        self.avg_dl: float = 0.0
        self.n_docs: int = 0

    def index(self, documents: list[tuple[str, str]]) -> None:
        """Index a list of (doc_id, text) tuples."""
        self.corpus = []
        self.doc_freqs = Counter()
        self.doc_lens = []

        for doc_id, text in documents:
            tokens = tokenize(text)
            self.corpus.append((doc_id, tokens))
            self.doc_lens.append(len(tokens))
            seen = set(tokens)
            for t in seen:
                self.doc_freqs[t] += 1

        self.n_docs = len(self.corpus)
        self.avg_dl = sum(self.doc_lens) / self.n_docs if self.n_docs else 1.0

    def search(self, query: str, top_k: int = 10) -> list[tuple[str, float]]:
        """Search the index. Returns list of (doc_id, score) sorted desc."""
        query_tokens = tokenize(query)
        if not query_tokens or not self.corpus:
            return []

        scores = []
        for idx, (doc_id, doc_tokens) in enumerate(self.corpus):
            score = 0.0
            dl = self.doc_lens[idx]
            tf_map = Counter(doc_tokens)

            for qt in query_tokens:
                if qt not in tf_map:
                    continue
                tf = tf_map[qt]
                df = self.doc_freqs.get(qt, 0)
                idf = math.log((self.n_docs - df + 0.5) / (df + 0.5) + 1.0)
                tf_norm = (tf * (self.k1 + 1)) / (tf + self.k1 * (1 - self.b + self.b * dl / self.avg_dl))
                score += idf * tf_norm

            if score > 0:
                scores.append((doc_id, score))

        scores.sort(key=lambda x: x[1], reverse=True)
        return scores[:top_k]


def detect_search_tier() -> int:
    """Detect best available search tier.

    Returns:
        1: BM25 only
        2: Local embeddings (ollama, sentence-transformers, fastembed)
        3: API embeddings (OpenAI)
    """
    from palaia.embeddings import detect_providers

    providers = detect_providers()
    for p in providers:
        if p["available"]:
            if p["name"] == "openai":
                return 3
            elif p["name"] in ("ollama", "sentence-transformers", "fastembed"):
                return 2
    return 1


def _resolve_semantic_provider(config: dict):
    """Resolve the semantic embedding provider respecting embedding_chain config.

    Reads ``embedding_chain`` from *config*, iterates over its entries (skipping
    ``"bm25"``), and returns the first provider that can be instantiated.
    Falls back to ``auto_detect_provider()`` when the chain is absent, empty,
    contains only ``"bm25"``, or none of its semantic entries are available.
    """
    chain = config.get("embedding_chain")
    if chain and isinstance(chain, list):
        models = _resolve_embedding_models(config)
        available = {p["name"] for p in detect_providers() if p["available"]}
        for name in chain:
            if name == "bm25":
                continue
            if name not in available:
                continue
            try:
                return _create_provider(name, models.get(name))
            except (ImportError, ValueError):
                continue
    # No chain configured or no chain provider available → legacy fallback
    return auto_detect_provider(config)


class SearchEngine:
    """Unified hybrid search: BM25 + semantic embeddings."""

    def __init__(self, store, config: dict | None = None):
        self.store = store
        self.bm25 = BM25()
        self.config = config or store.config
        self._provider = None

    @property
    def provider(self):
        if self._provider is None:
            self._provider = _resolve_semantic_provider(self.config)
        return self._provider

    @property
    def has_embeddings(self) -> bool:
        return not isinstance(self.provider, BM25Provider)

    def build_index(self, include_cold: bool = False, agent: str | None = None) -> list[tuple[str, str, dict]]:
        """Build search index from store entries. Returns (doc_id, full_text, meta) list."""
        entries = self.store.all_entries(include_cold=include_cold, agent=agent)
        docs = []
        docs_with_meta = []
        for meta, body, tier in entries:
            doc_id = meta.get("id", "unknown")
            title = meta.get("title", "")
            tags = " ".join(meta.get("tags", []))
            full_text = f"{title} {tags} {body}"
            docs.append((doc_id, full_text))
            docs_with_meta.append((doc_id, full_text, meta))
        self.bm25.index(docs)
        return docs_with_meta

    def search(
        self,
        query: str,
        top_k: int = 10,
        include_cold: bool = False,
        project: str | None = None,
        agent: str | None = None,
        entry_type: str | None = None,
        status: str | None = None,
        priority: str | None = None,
        assignee: str | None = None,
        instance: str | None = None,
        before: str | None = None,
        after: str | None = None,
        cross_project: bool = False,
    ) -> list[dict]:
        """Search memories using hybrid ranking (BM25 + embeddings when available).

        Structured filters (type, status, priority, assignee, instance) use exact match,
        not embeddings.

        Temporal filters (before, after) filter by entry created timestamp.
        cross_project=True ignores project filter and searches across all projects.
        """
        docs_with_meta = self.build_index(include_cold=include_cold, agent=agent)

        # Apply structured filters (exact match, pre-BM25)
        if project and not cross_project:
            docs_with_meta = [(did, text, meta) for did, text, meta in docs_with_meta if meta.get("project") == project]
        if entry_type:
            docs_with_meta = [
                (did, text, meta) for did, text, meta in docs_with_meta if meta.get("type", "memory") == entry_type
            ]
        if status:
            docs_with_meta = [(did, text, meta) for did, text, meta in docs_with_meta if meta.get("status") == status]
        if priority:
            docs_with_meta = [
                (did, text, meta) for did, text, meta in docs_with_meta if meta.get("priority") == priority
            ]
        if assignee:
            docs_with_meta = [
                (did, text, meta) for did, text, meta in docs_with_meta if meta.get("assignee") == assignee
            ]
        if instance:
            docs_with_meta = [
                (did, text, meta) for did, text, meta in docs_with_meta if meta.get("instance") == instance
            ]

        # Temporal filters (Issue #74)
        if before:
            docs_with_meta = [
                (did, text, meta) for did, text, meta in docs_with_meta if meta.get("created", "") < before
            ]
        if after:
            docs_with_meta = [
                (did, text, meta) for did, text, meta in docs_with_meta if meta.get("created", "") > after
            ]

        if project or entry_type or status or priority or assignee or instance or before or after:
            # Rebuild BM25 index with filtered docs
            self.bm25.index([(did, text) for did, text, meta in docs_with_meta])

        # BM25 scores
        bm25_results = self.bm25.search(query, top_k=top_k * 2)  # get more candidates for hybrid
        bm25_scores = {doc_id: score for doc_id, score in bm25_results}

        # Normalize BM25 scores to [0, 1]
        max_bm25 = max(bm25_scores.values()) if bm25_scores else 1.0
        bm25_norm = {k: v / max_bm25 for k, v in bm25_scores.items()} if max_bm25 > 0 else {}

        # Embedding scores (if available)
        embed_norm = {}
        if self.has_embeddings and docs_with_meta:
            try:
                query_vec = self.provider.embed_query(query)
                # Only embed BM25 candidates + a few extra for recall
                candidate_ids = set(bm25_scores.keys())
                texts_to_embed = []
                ids_to_embed = []
                for doc_id, full_text, meta in docs_with_meta:
                    # Check cache first
                    cached = self.store.embedding_cache.get_cached(doc_id)
                    if cached:
                        sim = cosine_similarity(query_vec, cached)
                        embed_norm[doc_id] = sim
                    elif doc_id in candidate_ids or len(texts_to_embed) < top_k:
                        texts_to_embed.append(full_text)
                        ids_to_embed.append(doc_id)

                if texts_to_embed:
                    vectors = self.provider.embed(texts_to_embed)
                    model_name = getattr(self.provider, "model_name", None) or getattr(
                        self.provider, "model", "unknown"
                    )
                    for doc_id, vec in zip(ids_to_embed, vectors):
                        self.store.embedding_cache.set_cached(doc_id, vec, model=model_name)
                        sim = cosine_similarity(query_vec, vec)
                        embed_norm[doc_id] = sim
            except Exception as e:
                # If embedding fails, fall back to BM25 only
                import warnings

                warnings.warn(f"Embedding search failed, using BM25 only: {e}")
                embed_norm = {}

        # Combine scores: hybrid ranking
        all_ids = set(bm25_norm.keys()) | set(embed_norm.keys())
        combined = {}
        for doc_id in all_ids:
            bm25_s = bm25_norm.get(doc_id, 0.0)
            embed_s = embed_norm.get(doc_id, 0.0)
            if embed_norm:
                # Weighted combination: 40% BM25 + 60% embedding
                combined[doc_id] = 0.4 * bm25_s + 0.6 * embed_s
            else:
                combined[doc_id] = bm25_s

        # Sort by combined score
        ranked = sorted(combined.items(), key=lambda x: x[1], reverse=True)[:top_k]

        # Build output
        output = []
        for doc_id, score in ranked:
            entry = self.store.read(doc_id)
            if entry:
                meta, body = entry
                result_entry = {
                    "id": doc_id,
                    "score": round(score, 4),
                    "type": meta.get("type", "memory"),
                    "scope": meta.get("scope", "team"),
                    "title": meta.get("title", ""),
                    "tags": meta.get("tags", []),
                    "body": body[:200] + ("..." if len(body) > 200 else ""),
                    "tier": self._get_tier(doc_id),
                    "decay_score": meta.get("decay_score", 0),
                }
                # Include task fields if present
                if meta.get("status"):
                    result_entry["status"] = meta["status"]
                if meta.get("priority"):
                    result_entry["priority"] = meta["priority"]
                if meta.get("assignee"):
                    result_entry["assignee"] = meta["assignee"]
                if meta.get("due_date"):
                    result_entry["due_date"] = meta["due_date"]
                if meta.get("instance"):
                    result_entry["instance"] = meta["instance"]
                if meta.get("project"):
                    result_entry["project"] = meta["project"]
                output.append(result_entry)
        return output

    def _get_tier(self, entry_id: str) -> str:
        """Determine which tier an entry is in."""
        for tier in ("hot", "warm", "cold"):
            if (self.store.root / tier / f"{entry_id}.md").exists():
                return tier
        return "unknown"

    def search_info(self) -> dict:
        """Get info about current search configuration."""
        provider = self.provider
        provider_display = get_provider_display_info(provider)
        has_embed = self.has_embeddings
        return {
            "provider": provider_display,
            "has_embeddings": has_embed,
            "bm25_active": True,
            "semantic_active": has_embed,
        }
